   "help.intro": "Du bist {prof} am Anfang der Laufbahn. Behandle jeden Tag die Patienten im Terminplan und baue eine Bindung zu ihnen auf.",
   "help.l1": "<strong>Terminplan (Ψ):</strong> zeigt die Sitzungen des Tages. Tippe auf eine Karte, um den Fall zu sehen, und auf <em>Sitzung starten</em> (oder die Tür), um zu beginnen.",
   "help.l2": "<strong>Antworten:</strong> Jede Option ist ein anderer <strong>Ansatz</strong> (stützend, KVT, psychodynamisch ...). Er wirkt je nach Problem des Patienten mehr oder weniger gut. Gute Entscheidungen erhöhen die <strong>Bindung</strong> und geben <strong>EP</strong>.",
   "help.l3": "<strong>Akte:</strong> bewahrt auf, was du herausgefunden hast. Sie füllt sich nur, wenn du gute Fragen stellst.",
   "help.l4": "<strong>Handbuch:</strong> enthält die Störungsgruppen, ihre Kriterien und die Ansätze. Wenn du nicht weiterweißt, zahle Münzen, um die Gruppe des Falls zu sehen.",
   "help.l5": "<strong>Energie und Pausen:</strong> Jede Sitzung ist anstrengend. Zwischen den Sitzungen gibt es eine Pause: Interagiere mit den Gegenständen im Raum, um dich zu erholen.",
   "help.l6": "<strong>Münzen und Shop:</strong> Nach jeder Sitzung verdienst du Münzen, mit denen du Deko, Erweiterungen für Praxis und Zuhause sowie Kleidung kaufst.",
   "help.l7": "<strong>Tastatur:</strong> Nutze in einer Sitzung die Tasten <kbd>A</kbd> <kbd>B</kbd> <kbd>C</kbd> <kbd>D</kbd> (oder <kbd>1</kbd> bis <kbd>4</kbd>), um zu antworten.",
   "help.l8": "<strong>Stadt und Handy:</strong> Erkunde die Stadt (Kartensymbol), sprich mit den Bewohnern und achte auf die Öffnungszeiten. Jeder Patient kommt 4 Wochen lang wieder; Therapieanfragen kommen aufs Handy.",
