   "idx.wheel.x": "Dein dominantes Profil bringt in manchen Gesprächen einen Vorteil. Nach einer guten Antwort kann ein Extra-Dialog erscheinen.",
   "idx.works.t": "Umbauten, Freunde und Unterstützung",
   "idx.works.x": "Erweitere Wohnung und Klinik an den Baustationen. Im Freunde-Tab des Handys verabredest du Kaffees: je 3 enge Freunde gibt +1 Energie beim Aufwachen.",
