   "instr.harp": "Harfe",
   "instr.piano": "Klavier",
   "intro.1": "Montag, 6:45 Uhr. Der Wecker hört nicht auf. Heute ist dein erster Tag in der Klinik für Neurodiagnostik.",
   "intro.10": "{nome}: „Hallo ... bin ich hier richtig? Ich habe einen Termin. Ich bin ein bisschen nervös.“",
   "intro.10b": "Sitzung beginnen ▶",
   "intro.10v2": "{nome}: „Guten Tag ... bin ich hier richtig? Ich bin etwas ängstlich.“",
   "intro.10v3": "{nome}: „(leise) Hallo ... ich habe jetzt einen Termin. Entschuldigung, es ist mein erstes Mal in Therapie.“",
   "intro.1a": "Wecker ausschalten",
   "intro.2": "Bevor du gehst, ein kurzer Blick aufs Handy: Die Anmeldung hat eine Nachricht hinterlassen.",
   "intro.2a": "Nachrichten ansehen",
   "intro.2from": "Anmeldung der Klinik",
   "intro.2msg": "Guten Morgen, {doc}! Heute: Maria um 8:00 und Lucas um 9:00. Die Akten liegen schon in der Praxis.",
   "intro.3": "Du steckst dein Notizbuch in die Tasche und atmest tief durch.",
   "intro.3a": "Tasche nehmen und losgehen",
   "intro.4": "Der Weg zur Klinik ist kurz. Du gehst alles im Kopf durch: erst zuhören, dann etikettieren; erst stützen, dann beraten.",
   "intro.5": "Gute Betreuung beginnt mit der Bindung. Eine übereilte Diagnose vertreibt den Patienten.",
   "intro.6": "Auf dem Schild steht Klinik NeuroClin. Du holst den Schlüssel aus der Tasche.",
   "intro.6a": "Tür öffnen",
   "intro.7": "Das ist deine Praxis. Jede Sitzung dauert 50 Minuten. Im Lauf der Woche kannst du sie mit den verdienten Münzen gestalten und erweitern.",
   "intro.8": "Zwei Dinge helfen dir: die Patientenakte, die sich füllt, während du Neues erfährst, und das Diagnosehandbuch mit Kriterien und Ansätzen.",
   "intro.9": "Klopf, klopf ... Jemand steht vor der Tür. Es ist {nome}, der erste Termin des Tages.",
   "intro.9b": "Dem Patienten die Tür öffnen ▶",
   "intro.next": "Weiter ▶",
   "intro.skip": "Intro überspringen ▶▶",
   "lang.gn.note": "Guaraní: Übersetzung ohne Prüfung durch Muttersprachler. Wenn Sie Guaraní sprechen, sind Ihre Korrekturen sehr willkommen!",
   "leave.confirm": "Sitzung verlassen? Der Fortschritt dieser Sitzung geht verloren.",
   "legend.anam": "<strong>Erstgespräch</strong><br>Erste Sitzung: Zuhören bei Beschwerde sowie Lebens- und Entwicklungsgeschichte.",
   "legend.dev": "<strong>Rückmeldegespräch</strong><br>Ergebnisse und Bericht werden mitgeteilt, mit Empfehlungen für Familie und Schule.",
