   "tip.energia.t": "⚡ Energie",
   "tip.energia.x": "Jede Sitzung ist anstrengend. Bei wenig Energie zählen deine Antworten weniger. In der Pause kannst du mit den Gegenständen im Raum interagieren, um dich zu erholen.",
   "tip.fala.t": "👂 Hör dem Patienten zu",
   "tip.fala.x": "Lies die Sprechblase aufmerksam: Sie enthält Hinweise darauf, was hinter der Beschwerde steckt.",
   "tip.ficha.t": "📋 Akte aktualisiert",
   "tip.ficha.x": "Der rote Punkt zeigt an, wenn du etwas Neues über den Patienten erfährst. Tippe auf die Akte, um nachzusehen.",
   "tip.investigar.t": "🔎 Untersuchen",
   "tip.investigar.x": "Klicke hier, um direkt nach Stimmung, Schlaf, Vorgeschichte, Risiken und anderen Bereichen zu fragen. Jede Antwort wird zu einem echten Hinweis für die Akte und die Diagnose.",
   "tip.manual.t": "📖 Diagnosehandbuch",
   "tip.manual.x": "Du willst Kriterien oder Ansätze nachsehen? Öffne das Handbuch. Wenn du bei der Gruppe des Falls unsicher bist, zahle {n} Münzen für einen Hinweis.",
   "tip.moedas.t": "🪙 Du hast Münzen verdient!",
   "tip.moedas.x": "Gib sie im Shop (die Tasche oben) aus, um die Praxis, dein Zuhause und deine Kleidung zu gestalten.",
   "tip.opcoes.t": "🎯 Wähle einen Ansatz",
   "tip.opcoes.x": "Jede Antwort ist ein anderer Ansatz (stützend, KVT ...). Er wirkt je nach Problem des Patienten mehr oder weniger gut. Du kannst auch die Tasten A, B, C und D benutzen.",
   "tip.porta.t": "🚪 Nächste Sitzung",
   "tip.porta.x": "Die Tür startet die nächste Sitzung im Terminplan. Das Ψ bringt dich immer zu dieser Seite zurück.",
   "tip.vinculo.t": "💖 Bindung",
   "tip.vinculo.x": "Diese Leiste zeigt das Vertrauen des Patienten (0 bis 100 %). Passende Ansätze erhöhen die Bindung; unpassende und Wertungen senken sie. Am Ende werden Bindung und Sterne zu Münzen.",
   "tips.again": "✓ Tipps wieder eingeschaltet",
