   "tut.appx1.t": "Patientenanhang",
   "tut.appx1.x": "Sieh, wer schon dran war, wer als Nächstes kommt, in welcher Phase die Sitzung steckt und ob deine diagnostische Hypothese richtig war.",
   "tut.appx2.t": "Spielindex",
   "tut.appx2.x": "Wenn du dich verirrst, listet der Index alles auf, was du im Spiel tun kannst, und wo du es findest.",
   "tut.break1.t": "Sorge in der Pause für dich",
   "tut.break1.x": "Tippe auf Gegenstände im Raum oder die Schaltflächen: Der Psychologe geht hin und führt die Aktion aus und erholt sich dabei. Du hast nur wenige Aktionen.",
   "tut.bubble.t": "Hör dem Patienten zu",
   "tut.choices.t": "Wähle, was du sagst",
   "tut.choices.x": "Jede Option ist ein anderer Ansatz. In dieser ersten Sitzung werden die Namen angezeigt; später verschwinden sie und du entscheidest selbst. Tippe auf eine Option, um zu antworten.",
   "tut.city1.t": "Drinnen erkunden",
   "tut.city1.x": "Jetzt kannst du dich im Ort bewegen: WASD oder Pfeiltasten am Computer, den Joystick am Handy, oder klicke/tippe auf den Boden, damit die Figur dorthin geht. Klicke auf eine Tür, ein Objekt oder eine Person, um hinzugehen und zu interagieren.",
   "tut.city2.t": "Minikarte",
   "tut.city2.x": "Die Minikarte zeigt dich (rosa Punkt), die wichtigen Objekte (gelb) und den Ausgang zur Karte (orange).",
   "tut.city3.t": "Zurück zur Karte",
   "tut.city3.x": "Tippe hier, um die Karte zu öffnen und woandershin zu gehen. Du kannst auch durch die 🚪-Tür jedes Ortes hinausgehen.",
   "tut.dayend1.t": "Die Uhr und die Nacht",
   "tut.dayend1.x": "Der Arbeitstag ist vorbei, aber der Tag geht weiter. Behalte die Uhr im Blick: Geschäfte haben Öffnungszeiten und schließen abends, und die Stadt wird dunkel. Die Tankstelle ist rund um die Uhr geöffnet.",
   "tut.dayend2.t": "Bummeln und schlafen",
   "tut.dayend2.x": "Nutze die Stadt-Schaltfläche zum Bummeln: Geh mit WASD, den Pfeiltasten oder dem Joystick und betritt Orte. Willst du den Tag beenden, geh in deine Wohnung und schlafe im Bett: Erst dann beginnt der nächste Tag.",
   "tut.decor1.t": "Der Raumplan",
   "tut.decor1.x": "Zieh jedes Möbelstück im Plan, wohin du willst. Berührt es ein anderes, verlässt den Raum oder versperrt den Weg, warnt dich das Spiel und lässt es nicht zu.",
   "tut.decor2.t": "Drehen und zurücksetzen",
   "tut.decor2.x": "Tippe ein Möbelstück an und nutze Drehen (oder R). „Ursprüngliche Stelle“ stellt es zurück. Größere Räume im Deko-Laden bieten mehr Platz.",
   "tut.dx.t": "Die diagnostische Hypothese",
   "tut.dx.x": "In der letzten Sitzung jeder Person (der 4.) wählen Sie die Hypothese, die am besten zu allem Gehörten passt. Richtig gibt einen Stern und Erfahrung. Danach folgt die Weiterleitung.",
   "tut.fauna1.t": "Stadttierchen",
   "tut.fauna1.x": "Krabben, Tauben, Schmetterlinge, Katzen und Fische leben hier. Sie erschrecken, wenn du zu nah kommst; geh langsam, um sie aus der Nähe zu sehen.",
   "tut.feedback.t": "Die Wirkung deiner Worte",
   "tut.feedback.x": "Hier siehst du, welchen Ansatz du genutzt hast, ob er gewirkt hat und warum. Derselbe Satz kann bei einem Patienten gut ankommen und bei einem anderen schlecht.",
   "tut.ficha.t": "Die Akte",
   "tut.ficha.x": "Hier siehst du, was du herausfindest. Sie beginnt fast leer und füllt sich, wenn du gute Fragen stellst.",
   "tut.fu.t": "Verlauf",
   "tut.fu.x": "Jede Person kommt 4-mal wieder, zweimal pro Woche. Diagnose und Weiterleitung folgen erst in der 4. Sitzung; danach kann sie um eine Fortsetzung der Therapie bitten. Die Anfrage kommt aufs Handy.",
   "tut.manual.t": "Das Diagnosehandbuch",
   "tut.manual.x": "Dein Nachschlagewerk: Störungen, Kriterien und therapeutische Ansätze. Öffne es bei Zweifeln, auch bei der Wahl der abschließenden Hypothese.",
   "tut.map1.t": "Die Stadtkarte",
   "tut.map1.x": "Hier wählst du, wohin du gehst. Die Stadt hat Bereiche: die Hauptstraße (Klinik, Wohnung und Geschäfte, die du zu Fuß erkundest), den Strand, den Platz und das Viertel der Patienten.",
   "tut.map2.t": "Auf der Karte fahren",
   "tut.map2.x": "Steuere das Auto mit den Pfeiltasten, WASD oder dem Joystick zu einem Ort und tippe auf Betreten (oder drücke E). Du kannst den Ort auch direkt antippen.",
   "tut.map3.t": "Behalte die Uhr im Auge",
   "tut.map3.x": "Jeder Weg dauert etwa 15 Minuten. Zu spät zu einer Sitzung zu kommen kostet Bindung, also prüfe immer die Uhrzeit.",
   "tut.mind1.t": "Denkspielothek",
   "tut.mind1.x": "Geh zu einem Spiel und tippe auf die Aktionstaste. Jedes Minispiel beruht auf einem echten Test und erklärt am Ende, was es trainiert. Die Tagesbelohnung gibt es beim ersten Spiel.",
   "tut.npc1.t": "Plaudern schafft Freundschaften",
   "tut.npc1.x": "Sprich an verschiedenen Tagen mit derselben Person. Nach drei Gesprächen wird sie zur Freundin und beginnt, Geschenke zu machen.",
   "tut.opts1.t": "Optionen: nach deinem Geschmack",
   "tut.opts1.x": "Hier änderst du Sprache, Schrift und Textgröße, helles/dunkles Design, Ton und Musik, Leistungsmodus und interaktive Aktivitäten. Alles lässt sich jederzeit ändern.",
   "tut.pets1.t": "Deine Haustiere",
   "tut.pets1.x": "Kümmere dich jeden Tag um deine Haustiere: Füttern, Spielen und Streicheln erhöhen die Bindung. Gut versorgt helfen sie in Sitzungen.",
   "tut.phone1.t": "Handynachrichten",
   "tut.phone1.x": "Nachrichten über kommende Patienten treffen hier mit Tag und Uhrzeit ein. Lies sie vor jeder Sitzung: Sie enthalten Hinweise.",
   "tut.shop1.t": "Gekauft wird nur in Geschäften",
   "tut.shop1.x": "Zu Hause kannst du nur ansehen und benutzen, was du besitzt. Zum Kaufen geh auf der Karte zum passenden Geschäft. Gesperrte Artikel zeigen, wo du sie findest.",
   "tut.souv1.t": "Anstecker und Accessoires",
   "tut.souv1.x": "Hier wählst du Flaggen, Anliegen, Brillen und Schmuck. Was du kaufst, erscheint daneben an deiner Figur.",
   "tut.station1.t": "Objekte und Türen",
   "tut.station1.x": "Wenn du in die Nähe von etwas Benutzbarem kommst, erscheint diese Schaltfläche mit dem Namen der Aktion. Tippe darauf oder drücke E.",
   "tut.street1.t": "Die Hauptstraße",
   "tut.street1.x": "Geh die Straße entlang, komm nahe an die Tür eines Gebäudes (oder klicke darauf) und drücke E zum Betreten. Die Schilder zeigen die Öffnungszeiten: Geschlossene Geschäfte sind abgedunkelt und mit einem Schloss versehen. Beim Verlassen kommst du zur selben Tür zurück.",
   "tut.uni1.t": "Vorlesungen an der Universität",
   "tut.uni1.x": "Wähle eine Vorlesung, lies die Kriterien des Handbuchs und mache dann das Quiz. Beim ersten Bestehen gibt es Erfahrung und Geld; ein Fehler zeigt die richtige Antwort.",
   "tut.vinculo.t": "Bindung und Energie",
   "tut.vinculo.x": "Die Bindung zeigt, wie sehr der Patient dir vertraut, und steigt mit guten Entscheidungen. Die Energie sinkt mit jeder Sitzung: Sorge in den Pausen für dich.",
   "uni.diploma": "🎓 Du hast alle Vorlesungen bestanden! Vollständiges Diplom.",
   "uni.exam": "Quiz machen",
   "uni.examof": "Quiz",
