   "help.intro": "Olet uransa alussa oleva {prof}. Tapaa joka päivä aikataulun potilaat ja rakenna heihin luottamus.",
   "help.l1": "<strong>Aikataulu (Ψ):</strong> näyttää päivän istunnot. Napauta korttia nähdäksesi tapauksen ja <em>Aloita istunto</em> (tai ovi) aloittaaksesi.",
   "help.l2": "<strong>Vastaaminen:</strong> jokainen vaihtoehto on eri <strong>lähestymistapa</strong> (tukeva, KKT, psykodynaaminen…). Se toimii enemmän tai vähemmän hyvin potilaan ongelmasta riippuen. Hyvät valinnat nostavat <strong>luottamusta</strong> ja antavat <strong>kokemusta</strong>.",
   "help.l3": "<strong>Kortti:</strong> säilyttää sen, minkä olet saanut selville. Se täyttyy vain, kun kysyt hyviä kysymyksiä.",
   "help.l4": "<strong>Käsikirja:</strong> sisältää häiriöryhmät, niiden kriteerit ja lähestymistavat. Jos olet eksyksissä, maksa kolikoita nähdäksesi tapauksen ryhmän.",
   "help.l5": "<strong>Energia ja tauot:</strong> jokainen istunto väsyttää. Istuntojen välillä on tauko: toimi huoneen esineiden kanssa palautuaksesi.",
   "help.l6": "<strong>Kolikot ja kauppa:</strong> jokaisen istunnon jälkeen ansaitset kolikoita, joilla ostat sisustusta, vastaanoton ja kodin laajennuksia sekä vaatteita.",
   "help.l7": "<strong>Näppäimistö:</strong> istunnon aikana voit vastata näppäimillä <kbd>A</kbd> <kbd>B</kbd> <kbd>C</kbd> <kbd>D</kbd> (tai <kbd>1</kbd>–<kbd>4</kbd>).",
   "help.l8": "<strong>Kaupunki ja puhelin:</strong> kierrä kaupunkia (karttakuvake), puhu asukkaille ja seuraa kauppojen aukioloaikoja. Jokainen potilas palaa 4 viikon ajan; terapiapyynnöt tulevat puhelimeen.",
   "help.l9": "<strong>Pelin hakemisto:</strong> aloitusnäytöllä 🧭-painike listaa kaikki järjestelmät (meri, kasino, remontit, ystävät, musiikki, saavutukset…) ja missä ne ovat.",
   "help.replay": "↺ Katso opastusvinkit uudelleen",
   "help.title": "Pelaamisen ohjeet",
