   "idx.ach.t": "Saavutukset ja Vartijat",
   "idx.ach.x": "Suorita haasteita saavutusten saamiseksi. Löydä neljä Vartijaa kaupungista täyttääksesi Vartijoiden legendan.",
   "idx.appx.t": "Liite ja suunnitelma",
   "idx.appx.x": "Katso, ketkä on tavattu, kuka on seuraava ja viikon yhteenveto.",
   "idx.break.t": "Tauko istuntojen välillä",
   "idx.break.x": "Kymmenen minuuttia itsestäsi huolehtimiseen: napauta huoneen esineitä ja palauta energiaa.",
   "idx.city.t": "Kävele kaupungilla",
   "idx.city.x": "Kuvake 🗺️: kävele WASD-näppäimillä tai ohjaimella. Löydä paikkoja, juttele ja pidä silmällä seuraavan istuntosi aikaa.",
   "idx.cloud.t": "Tili ja tulostaulu",
   "idx.cloud.x": "Kun palvelin on päällä: synkronointi laitteiden välillä ja pisteiden vertailu.",
   "idx.consult.t": "Istunnot potilaiden kanssa",
   "idx.consult.x": "Jokaisessa istunnossa on 4 tai 5 keskusteluvaihetta. Valitse lähestymistapa, joka sopii parhaiten ihmiseen ja hetkeen.",
   "idx.culture.t": "Ostoskeskus, kielet ja historia",
   "idx.culture.x": "Ostoskeskuksen kielikaupassa vaihdat pelin kielen (guarani mukaan lukien) ja luet psykologian historiasta.",
   "idx.decor.t": "Koti ja vastaanotto",
   "idx.decor.x": "Sisusta ja laajenna vastaanottoasi, odotushuonettasi ja keittiötäsi kaupassa.",
   "idx.dress.t": "Mukautus ja sovituskoppi",
   "idx.dress.x": "Vaihda kasvot, hiukset ja vaatteet milloin haluat. Sovita vaatteita sovituskopissa ennen ostamista.",
   "idx.dx.t": "Diagnostinen hypoteesi",
   "idx.dx.x": "Valitse jokaisen istunnon lopussa johdonmukaisin hypoteesi. Oikea vastaus tuo ylimääräisen tähden.",
   "idx.fauna.t": "Eläinopas",
   "idx.fauna.x": "Kaikki kaupungin, rannan ja meren eläimet elinympäristöineen ja hauskoine faktoineen. Löydät ne kävelemällä lähelle.",
   "idx.follow.t": "Seuranta 4 istunnon aikana",
   "idx.follow.x": "Jokainen potilas palaa 4 viikon ajan. Diagnoosi varmistuu vasta 4. istunnossa; sillä välin vastaat puhelimella terapiapyyntöihin.",
   "idx.help": "Kaikki, mitä voit tehdä, ja missä.",
   "idx.leisure.t": "Kuntosali, kauppa, pikaruoka ja kasino",
   "idx.leisure.x": "Huolehdi voimista ja mielialasta, käy ostoksilla ja pelaa kasinon minipelejä (älä liioittele!).",
   "idx.live.t": "Elävä kaupunki",
   "idx.live.x": "Asukkaat noudattavat rutiinejaan, kaupat aukeavat ja sulkeutuvat ja yöllä katu pimenee. Puhu muille kuin potilaille: jos vakuutat heidät, he varaavat terapian seuraavalle viikolle.",
   "idx.manual.t": "Diagnoosikäsikirja",
   "idx.manual.x": "Kymmenien häiriöiden kriteerit ja lähestymistavat. Avaa se istunnon aikana aina epäillessäsi.",
   "idx.mind.t": "Mielen pelihuone (minipelit)",
   "idx.mind.x": "Pääkadulla: 10 peliä oikeisiin testeihin perustuen (Schulte, Trail Making, Stroop, numerosarja, Simon, Corsi, Go/No-Go, 1-back, tunneparit ja hengitys). Jokainen kertoo, mitä se harjoittaa; päivän palkinto tulee ensimmäisestä pelistä.",
   "idx.music.t": "Musiikki ja soittimet",
   "idx.music.x": "Asetuksissa valitset taustamusiikin soittimen (kellot, piano, huilu tai harppu). Jokaisella hahmolla on oma teemansa keskustelussa ja jokaisella potilaalla oma sävynsä istunnossa.",
   "idx.npc.t": "Ystävyydet",
   "idx.npc.x": "Puhu kaupungin ihmisille eri päivinä. Ystävät antavat lahjoja.",
   "idx.opts.t": "Asetukset",
   "idx.opts.x": "Kieli, ääni, 3D, vinkit ja oppimistila, joka näyttää lähestymistavat.",
   "idx.pets.t": "Lemmikit",
   "idx.pets.x": "Adoptoi tavallisia tai eksoottisia lemmikkejä. Pidä niistä huolta: ne auttavat istunnoissa ja seuraavat sinua kaupungilla.",
   "idx.phone.t": "Puhelin",
   "idx.phone.x": "Potilaiden viestit sekä päivä ja kellonaika, jolloin ne saapuivat.",
   "idx.sea.t": "Meri, laivat ja akvaario",
   "idx.sea.x": "Soudan rannalta merirosvolaivalle, Lentävälle hollantilaiselle (vain yöllä) ja merenalaiselle railolle. Vakuuta asukkaat ja kerää olentoja akvaarioon.",
   "idx.secret.t": "Salainen tila",
   "idx.secret.x": "Juhlapyhien vieraat aloitusvalikossa.",
   "idx.shop.t": "Kaupat ja vaatteet",
   "idx.shop.x": "Vaatekauppa ja putiikki (yksinoikeuskappaleet) hahmosi pukemiseen.",
   "idx.souv.t": "Matkamuistot ja pinssit",
   "idx.souv.x": "Liput, aatteet ja liikkeet, lasit ja korut päälle pantaviksi.",
   "idx.title": "🧭 Pelin hakemisto",
   "idx.uni.t": "Yliopisto",
   "idx.uni.x": "Vastaa käsikirjan kriteerejä koskeviin kysymyksiin ja ansaitse kokemusta ja rahaa.",
   "idx.wheel.t": "Psykologin pyörä",
   "idx.wheel.x": "Hallitseva profiilisi antaa etua tietyissä keskusteluissa. Hyvän vastauksen jälkeen voi ilmestyä lisädialogi.",
   "idx.works.t": "Remontit, ystävät ja tukiverkosto",
   "idx.works.x": "Laajenna asunto ja klinikka remonttipisteillä. Puhelimen Ystävät-välilehdellä sovit kahvit: joka 3. läheinen ystävä antaa +1 energiaa heräämiseen.",
