   "instr.harp": "Harppu",
   "instr.piano": "Piano",
   "intro.1": "Maanantai, kello 6.45. Herätyskello ei lopeta soimistaan. Tänään on ensimmäinen päiväsi neuroarviointiklinikalla.",
   "intro.10": "{nome}: ”Hei… onko tämä se paikka, johon varasin ajan? Jännittää vähän.”",
   "intro.10b": "Aloita istunto ▶",
   "intro.10v2": "{nome}: ”Hyvää päivää... olenko oikeassa paikassa? Jännittää vähän.”",
   "intro.10v3": "{nome}: ”(hiljaa) Hei... minulla on nyt aika. Anteeksi, tämä on ensimmäinen kertani terapiassa.”",
   "intro.1a": "Sammuta herätyskello",
   "intro.2": "Ennen lähtöä nopea vilkaisu puhelimeen: vastaanotto on jättänyt viestin.",
   "intro.2a": "Katso viestit",
   "intro.2from": "Klinikan vastaanotto",
   "intro.2msg": "Huomenta, {doc}! Tänään: Maria kello 8.00 ja Lucas kello 9.00. Potilaskortit ovat jo vastaanotolla.",
   "intro.3": "Laitat muistikirjasi laukkuun ja vedät syvään henkeä.",
   "intro.3a": "Ota laukku ja lähde",
   "intro.4": "Matka klinikalle on lyhyt. Kertaat mielessäsi: kuuntele ennen leimaamista, tue ennen neuvomista.",
   "intro.5": "Hyvä hoito alkaa luottamuksesta. Hätiköity diagnoosi karkottaa potilaan.",
   "intro.6": "Kyltissä lukee NeuroClin-klinikka. Otat avaimen laukustasi.",
   "intro.6a": "Avaa ovi",
   "intro.7": "Tämä on vastaanottosi. Jokainen istunto kestää 50 minuuttia. Viikon aikana voit sisustaa ja laajentaa sitä ansaitsemillasi kolikoilla.",
   "intro.8": "Kaksi asiaa auttaa: potilaskortti, joka täyttyy sitä mukaa kun saat selville asioita, sekä diagnoosikäsikirja, jossa on kriteerit ja lähestymistavat.",
   "intro.9": "Koputus… Joku on ovella. Se on {nome}, päivän ensimmäinen vastaanotto.",
   "intro.9b": "Avaa ovi potilaalle ▶",
   "intro.next": "Jatka ▶",
   "intro.skip": "Ohita intro ▶▶",
   "lang.gn.note": "Guarani: käännös tehty ilman äidinkielisen tarkistusta. Jos puhut guaranin, korjauksesi ovat tervetulleita!",
   "lang.label": "Kieli",
   "leave.confirm": "Poistutaanko istunnosta? Tämän istunnon edistyminen menetetään.",
   "legend.anam": "<strong>Alkuhaastattelu</strong><br>Ensimmäinen istunto: vaivan, elämänhistorian ja kehityshistorian kuunteleminen.",
   "legend.dev": "<strong>Palautekeskustelu</strong><br>Tulosten ja lausunnon kertominen sekä ohjeet perheelle ja koululle.",
   "legend.test": "<strong>Testaus</strong><br>Mittareiden käyttö ja kliininen havainnointi standardoidun protokollan mukaan.",
