   "tut.city1.x": "Nyt voit kävellä paikan sisällä: WASD tai nuolet tietokoneella, ohjain puhelimella, tai klikkaa/napauta maata, niin hahmo menee sinne. Klikkaa ovea, esinettä tai henkilöä mennäksesi ja toimiaksesi.",
   "tut.city2.t": "Minikartta",
   "tut.city2.x": "Minikartta näyttää sinut (vaaleanpunainen piste), tärkeät esineet (keltainen) ja uloskäynnin kartalle (oranssi).",
   "tut.city3.t": "Takaisin kartalle",
   "tut.city3.x": "Napauta tästä avataksesi kartan ja mennäksesi muualle. Voit myös poistua jokaisen paikan 🚪-ovesta.",
   "tut.dayend1.t": "Kello ja yö",
   "tut.dayend1.x": "Työpäivä on ohi, mutta päivä jatkuu. Seuraa kelloa: kaupoilla on aukioloajat ja ne sulkeutuvat illalla, ja kaupunki pimenee. Bensa-asema on auki vuorokauden ympäri.",
   "tut.dayend2.t": "Kävely ja nukkuminen",
   "tut.dayend2.x": "Käytä kaupunkipainiketta kävelläksesi: liiku WASD-näppäimillä, nuolilla tai ohjaimella ja astu paikkoihin. Kun haluat päättää päivän, mene asuntoosi ja nuku sängyssä: vasta silloin seuraava päivä alkaa.",
   "tut.decor1.t": "Huoneen pohjapiirros",
   "tut.decor1.x": "Vedä kaluste pohjapiirroksessa minne haluat. Jos se osuu toiseen, menee huoneen ulkopuolelle tai tukkii kulkuväylän, peli varoittaa eikä salli sitä.",
   "tut.decor2.t": "Käännä ja palauta",
   "tut.decor2.x": "Napauta kalustetta ja käytä Käännä-toimintoa (tai R). ”Alkuperäinen paikka” palauttaa sen alkuun. Suuremmat huoneet sisustuskaupassa antavat lisää tilaa.",
   "tut.dx.t": "Diagnostinen hypoteesi",
   "tut.dx.x": "Jokaisen potilaan viimeisessä (4.) istunnossa valitset hypoteesin, joka sopii parhaiten kuulemaasi. Oikea vastaus tuo tähden ja kokemusta. Sen jälkeen tulee jatkosuositus.",
   "tut.fauna1.t": "Kaupungin eläimet",
   "tut.fauna1.x": "Täällä asuu rapuja, kyyhkysiä, perhosia, kissoja ja kaloja. Ne säikähtävät, jos tulet liian lähelle; kulje hitaasti nähdäksesi ne läheltä.",
   "tut.feedback.t": "Sanomasi vaikutus",
   "tut.feedback.x": "Tästä näet, mitä lähestymistapaa käytit, toimiko se ja miksi. Sama lause voi toimia yhdelle potilaalle ja huonosti toiselle.",
   "tut.ficha.t": "Potilaskortti",
   "tut.ficha.x": "Tähän kertyy se, mitä saat selville. Se on alussa lähes tyhjä ja täyttyy, kun kysyt hyviä kysymyksiä.",
   "tut.fu.t": "Seuranta",
   "tut.fu.x": "Jokainen potilas tulee 4 kertaa, kaksi kertaa viikossa. Diagnoosi ja jatkosuositus tulevat vasta 4. istunnossa, ja sen jälkeen potilas voi pyytää terapian jatkoa. Pyyntö tulee puhelimeen.",
   "tut.hint": "Napauta korostettua aluetta",
   "tut.manual.t": "Diagnoosikäsikirja",
   "tut.manual.x": "Nopea apusi: häiriöt, kriteerit ja terapeuttiset lähestymistavat. Avaa se epäillessäsi, myös lopullista hypoteesia valitessasi.",
   "tut.map1.t": "Kaupungin kartta",
   "tut.map1.x": "Täällä valitset, minne menet. Kaupungissa on alueita: pääkatu (klinikka, asunto ja kaupat, joissa kävelet), ranta, tori ja potilaiden kaupunginosa.",
   "tut.map2.t": "Ajaminen kartalla",
   "tut.map2.x": "Aja auto paikkaan nuolinäppäimillä, WASD:llä tai ohjaimella ja napauta Astu sisään (tai paina E). Voit myös napauttaa paikkaa suoraan.",
   "tut.map3.t": "Pidä kelloa silmällä",
   "tut.map3.x": "Jokainen matka kestää noin 15 minuuttia. Istunnosta myöhästyminen maksaa luottamusta, joten tarkista aina aika.",
   "tut.mind1.t": "Mielen pelihuone",
   "tut.mind1.x": "Mene pelin luo ja napauta toimintopainiketta. Jokainen minipeli perustuu oikeaan testiin ja kertoo lopuksi, mitä se harjoittaa. Päivän palkinto tulee ensimmäisestä pelistä.",
   "tut.next": "Jatka ▶",
   "tut.npc1.t": "Jutteleminen luo ystävyyksiä",
   "tut.npc1.x": "Puhu samalle ihmiselle eri päivinä. Kolmen keskustelun jälkeen hänestä tulee ystävä, ja hän alkaa antaa lahjoja.",
   "tut.opts1.t": "Asetukset: tee siitä omasi",
   "tut.opts1.x": "Täällä voit vaihtaa kielen, fontin ja tekstin koon, vaalean/tumman teeman, äänet ja musiikin, suorituskykytilan ja interaktiiviset toiminnot. Kaiken voi muuttaa milloin tahansa.",
   "tut.pets1.t": "Lemmikkisi",
   "tut.pets1.x": "Pidä lemmikeistäsi huolta joka päivä: ruokinta, leikki ja hellittely vahvistavat sidettä. Hyvin hoidettuina ne auttavat istunnoissa.",
   "tut.phone1.t": "Puhelinviestit",
   "tut.phone1.x": "Viestit tulevista potilaista saapuvat tänne päivän ja kellonajan kanssa. Lue ne ennen jokaista istuntoa: niissä on vihjeitä.",
   "tut.shop1.t": "Ostaminen vain kaupoissa",
   "tut.shop1.x": "Kotona voit vain katsella ja käyttää omistamaasi. Ostaaksesi mene oikeaan kauppaan kartalla. Lukitut tuotteet kertovat, mistä ne löytyvät.",
   "tut.skip": "Ohita opastus",
   "tut.souv1.t": "Pinssit ja asusteet",
   "tut.souv1.x": "Täältä valitset liput, aatteet, lasit ja korut. Ostamasi näkyy viereisessä hahmossasi.",
   "tut.station1.t": "Esineet ja ovet",
   "tut.station1.x": "Kun tulet lähelle jotakin käytettävää, tämä painike ilmestyy toiminnon nimellä. Napauta sitä tai paina E.",
   "tut.street1.t": "Pääkatu",
   "tut.street1.x": "Kävele kadulla, mene rakennuksen oven lähelle (tai klikkaa ovea) ja paina E astuaksesi sisään. Kyltit näyttävät aukioloajat: suljetut liikkeet on tummennettu ja niissä on lukko. Kun tulet ulos, palaat samalle ovelle.",
   "tut.uni1.t": "Yliopiston luennot",
   "tut.uni1.x": "Valitse luento, lue käsikirjan kriteerit ja tee sitten koe. Ensimmäinen läpäisy antaa kokemusta ja rahaa; virhe näyttää oikean vastauksen.",
   "tut.vinculo.t": "Luottamus ja energia",
   "tut.vinculo.x": "Luottamus näyttää, kuinka paljon potilas luottaa sinuun, ja nousee hyvillä valinnoilla. Energia laskee jokaisen istunnon myötä: huolehdi siitä tauoilla.",
   "uni.again": "Toinen kysymys",
   "uni.diploma": "🎓 Läpäisit kaikki luennot! Täysi tutkinto.",
   "uni.exam": "Tee koe",
   "uni.examof": "Koe",
