   "uni.finish": "Katso tulos",
   "uni.intro": "Jokainen luento tiivistää yhden käsikirjan ryhmän. Lue luento ja tee koe: 4 kysymystä, läpäisyyn tarvitaan 3 oikeaa. Läpäisty: {n}/{total}.",
   "uni.lesson": "Luento: lue tarkasti. Nämä ovat jokaisen häiriön tärkeimmät kriteerit, erotusdiagnoosit ja kliininen vinkki.",
