   "ph.tab.pedidos": "Requests",
   "ph.pedidos.sobre": "Inside the room you only reach what the person tells you. The school sees the routine, the doctor sees the body, the family saw the beginning, and whoever treated them before has the records. Each request costs coins and days of waiting — not session time.",
