   "tut.vez.t": "One voice at a time",
   "tut.vez.x": "When more than one person speaks, each gets their own bubble — and the portrait beside it changes along. The ▾ arrow under the bubble (or a tap on it) calls whoever speaks next. The options only show up once everyone has finished.",
   "tut.escuta.t": "Listen and ask",
