   "fu.tx.answer": "L'orientation la plus adaptée était : {name}.",
   "fu.tx.disclaimer": "Rappel : les psychologues ne prescrivent pas de médicaments ; en cas d'indication, on oriente vers un médecin. Ceci est un jeu et ne remplace pas une évaluation professionnelle.",
   "fu.tx.familia": "Guidance familiale et scolaire + suivi",
