   "fu.tx.head": "Choisissez l'orientation",
   "fu.tx.prompt": "Pour clore le cycle avec {name} : quelle orientation recommandez-vous ?",
   "fu.tx.psico": "Psychothérapie continue",
   "fu.tx.psicpsiq": "Psychothérapie + évaluation psychiatrique",
   "fu.tx.right": "Orientation adaptée ! +5 d'expérience",
   "fu.tx.wrong": "Une autre orientation serait préférable",
   "fu.txwhy.familia": "Chez l'enfant et l'adolescent, l'environnement fait partie du traitement : guider la famille et l'école est souvent aussi important que la thérapie.",
   "fu.txwhy.grupo": "Indiqué en cas d'usage problématique d'alcool ou d'autres substances : services spécialisés et groupes de soutien soutiennent le changement.",
   "fu.txwhy.psico": "Indiquée quand le tableau répond bien à la psychothérapie et qu'il n'y a ni risque ni symptômes nécessitant un avis médical.",
   "fu.txwhy.psicpsiq": "Indiquée en cas de symptômes intenses, de forte altération du fonctionnement ou de risque : le psychiatre évalue si un traitement médicamenteux est nécessaire. C'est le médecin qui prescrit, jamais le psychologue.",
