   "fu.week": "Semaine {w} sur {t}",
   "fu.weekroll": "Semaine {n} terminée ! La semaine {m} commence lundi. Les patients en thérapie chez vous ont rapporté {c} pièces.",
   "guide.count": "Découverts : {n} sur {t}",
   "guide.help": "Les animaux qui vivent en ville, sur la plage et dans la mer. Passez près de chacun pour le découvrir ; ceux pas encore vus apparaissent en ombre.",
   "guide.hint": "Pas encore vu. Cherchez à :",
   "guide.title": "🦋 Guide de la faune",
   "guide.unknown": "???",
   "guide.where": "Où il vit",
   "hair.bob": "Carré ondulé",
   "help.intro": "Vous êtes {prof} en début de carrière. Chaque jour, recevez les patients de l'agenda et construisez un lien avec eux.",
   "help.l1": "<strong>Agenda (Ψ) :</strong> affiche les séances du jour. Touchez une carte pour voir le cas, puis <em>Commencer la séance</em> (ou la porte) pour démarrer.",
   "help.l2": "<strong>Répondre :</strong> chaque option est une <strong>approche</strong> différente (soutien, TCC, psychodynamique...). Elle fonctionne plus ou moins bien selon le problème du patient. Les bons choix augmentent le <strong>Lien</strong> et donnent de l'<strong>XP</strong>.",
   "help.l3": "<strong>Dossier :</strong> garde ce que vous avez découvert. Il ne se remplit que si vous posez de bonnes questions.",
   "help.l4": "<strong>Manuel :</strong> contient les groupes de troubles, leurs critères et les approches. Si vous êtes perdu, payez des pièces pour voir le groupe du cas.",
   "help.l5": "<strong>Énergie et pauses :</strong> chaque séance est fatigante. Entre les séances, il y a une pause : interagissez avec les objets de la pièce pour récupérer.",
   "help.l6": "<strong>Pièces et boutique :</strong> après chaque séance, vous gagnez des pièces, qui servent à acheter de la décoration, des agrandissements pour le cabinet et la maison, et des vêtements.",
   "help.l7": "<strong>Clavier :</strong> pendant une séance, utilisez les touches <kbd>A</kbd> <kbd>B</kbd> <kbd>C</kbd> <kbd>D</kbd> (ou <kbd>1</kbd> à <kbd>4</kbd>) pour répondre.",
   "help.l8": "<strong>Ville et téléphone :</strong> promenez-vous en ville (icône de la carte), parlez aux habitants et surveillez les horaires des boutiques. Chaque patient revient pendant 4 semaines ; les demandes de thérapie arrivent sur le téléphone.",
   "help.l9": "<strong>Index du jeu :</strong> sur l'écran d'accueil, le bouton 🧭 liste tous les systèmes (mer, casino, travaux, amis, musique, succès…) et où les trouver.",
   "help.replay": "↺ Revoir les conseils du tutoriel",
   "help.title": "Comment jouer",
