   "idx.ach.t": "Succès et Gardiens",
   "idx.ach.x": "Relevez des défis pour gagner des succès. Trouvez les quatre Gardiens dans la ville pour accomplir La légende des Gardiens.",
   "idx.appx.t": "Annexe et agenda",
   "idx.appx.x": "Voyez qui a été vu, qui est le suivant et le bilan de la semaine.",
   "idx.break.t": "Pause entre les séances",
   "idx.break.x": "Dix minutes pour prendre soin de vous : touchez les objets de la pièce et récupérez de l'énergie.",
   "idx.city.t": "Se promener en ville",
   "idx.city.x": "Icône 🗺️ : marchez avec WASD ou le joystick. Découvrez des lieux, discutez et surveillez l'heure de votre prochaine séance.",
   "idx.cloud.t": "Compte et classement",
   "idx.cloud.x": "Avec le serveur actif : synchronisation entre appareils et comparaison des points.",
   "idx.consult.t": "Séances avec les patients",
   "idx.consult.x": "Chaque séance compte 4 ou 5 étapes de conversation. Choisissez l'approche qui convient le mieux à la personne et au moment.",
   "idx.culture.t": "Centre commercial, langues et histoire",
   "idx.culture.x": "Au centre commercial, changez la langue du jeu à la boutique des langues (guarani inclus) et lisez l'histoire de la psychologie.",
   "idx.decor.t": "Maison et cabinet",
   "idx.decor.x": "Décorez et agrandissez votre cabinet, votre salle d'attente et votre cuisine à la boutique.",
   "idx.dress.t": "Personnalisation et cabine d'essayage",
   "idx.dress.x": "Changez visage, cheveux et vêtements quand vous voulez. Essayez les articles en cabine avant d'acheter.",
   "idx.dx.t": "Hypothèse diagnostique",
   "idx.dx.x": "À la fin de chaque séance, choisissez l'hypothèse la plus cohérente. La bonne réponse rapporte une étoile en plus.",
   "idx.fauna.t": "Guide de la faune",
   "idx.fauna.x": "Tous les animaux de la ville, de la plage et de la mer, avec leur habitat et une anecdote. Découvrez-les en vous approchant.",
   "idx.follow.t": "Suivi en 4 séances",
   "idx.follow.x": "Chaque patient revient pendant 4 semaines. Le diagnostic n'est posé qu'à la 4e séance ; entre-temps, répondez aux demandes de thérapie sur le téléphone.",
   "idx.help": "Tout ce que vous pouvez faire, et où.",
   "idx.leisure.t": "Salle de sport, marché, snack et casino",
   "idx.leisure.x": "Prenez soin de votre énergie et de votre humeur, faites vos courses et amusez-vous avec les mini-jeux du casino (sans exagérer !).",
   "idx.live.t": "Ville vivante",
   "idx.live.x": "Les habitants suivent leur routine, les boutiques ouvrent et ferment, et la rue s'assombrit la nuit. Parlez aux non-patients : si vous les convainquez, ils prennent rendez-vous la semaine suivante.",
   "idx.manual.t": "Manuel diagnostique",
   "idx.manual.x": "Critères de dizaines de troubles et les approches. Ouvrez-le pendant une séance dès que vous hésitez.",
   "idx.mind.t": "Ludothèque de l'Esprit (mini-jeux)",
   "idx.mind.x": "Dans la rue principale : 10 jeux inspirés de vrais tests (Schulte, Trail Making, Stroop, empan de chiffres, Simon, Corsi, Go/No-Go, 1-back, paires d'émotions et respiration). Chacun explique ce qu'il entraîne ; la récompense du jour tombe à la première partie.",
   "idx.music.t": "Musique et instruments",
   "idx.music.x": "Dans Options, choisissez l'instrument de la bande-son (cloches, piano, flûte ou harpe). Chaque personnage a son thème en conversation et chaque patient sa tonalité en séance.",
   "idx.npc.t": "Amitiés",
   "idx.npc.x": "Parlez aux gens de la ville à différents jours. Les amis offrent des cadeaux.",
   "idx.opts.t": "Options",
   "idx.opts.x": "Langue, son, 3D, conseils et mode apprentissage, qui affiche les approches.",
   "idx.pets.t": "Animaux",
   "idx.pets.x": "Adoptez des animaux communs ou exotiques. Prenez-en soin : ils aident pendant les séances et vous suivent en ville.",
   "idx.phone.t": "Téléphone",
   "idx.phone.x": "Messages des patients avec le jour et l'heure d'arrivée.",
   "idx.sea.t": "Mer, navires et aquarium",
   "idx.sea.x": "Depuis la plage, ramez jusqu'au navire pirate, au Vaisseau fantôme (la nuit seulement) et à la faille sous-marine. Convainquez les habitants et collectez des créatures pour l'aquarium.",
   "idx.secret.t": "Mode secret",
   "idx.secret.x": "Visiteurs des fêtes dans le menu titre.",
   "idx.shop.t": "Boutiques et vêtements",
   "idx.shop.x": "Magasin de vêtements et boutique (pièces exclusives) pour habiller votre personnage.",
   "idx.souv.t": "Souvenirs et badges",
   "idx.souv.x": "Drapeaux, causes et mouvements, lunettes et bijoux à porter.",
   "idx.title": "🧭 Index du jeu",
   "idx.uni.t": "Université",
   "idx.uni.x": "Répondez à des questions sur les critères du Manuel et gagnez de l'expérience et de l'argent.",
   "idx.wheel.t": "Roue du psychologue",
   "idx.wheel.x": "Votre profil dominant donne un avantage dans certaines conversations. Après une bonne réponse, un dialogue supplémentaire peut apparaître.",
   "idx.works.t": "Travaux, amis et réseau de soutien",
   "idx.works.x": "Agrandissez l'appartement et la clinique aux postes de travaux. Dans l'onglet Amis du téléphone, organisez des cafés : tous les 3 amis proches, vous vous réveillez avec +1 d'énergie.",
   "info.age": "Âge",
   "info.complaint": "Plainte",
   "info.name": "Nom",
   "info.type": "Type",
