   "instr.harp": "Harpe",
   "instr.piano": "Piano",
   "intro.1": "Lundi, 6 h 45. Le réveil ne veut pas s'arrêter. Aujourd'hui, c'est votre premier jour à la clinique de neuro-évaluation.",
   "intro.10": "{nome} : « Bonjour... c'est bien ici que j'ai rendez-vous ? Je suis un peu nerveuse. »",
   "intro.10b": "Commencer la séance ▶",
   "intro.10v2": "{nome} : « Bonjour... suis-je au bon endroit ? Je suis un peu anxieuse. »",
   "intro.10v3": "{nome} : « (doucement) Bonjour... j'ai rendez-vous maintenant. Désolée, c'est ma première fois en thérapie. »",
   "intro.1a": "Éteindre le réveil",
   "intro.2": "Avant de partir, un coup d'œil rapide au téléphone : l'accueil a laissé un message.",
   "intro.2a": "Voir les messages",
   "intro.2from": "Accueil de la clinique",
   "intro.2msg": "Bonjour {doc} ! Aujourd'hui : Maria à 8 h et Lucas à 9 h. Les dossiers sont déjà au cabinet.",
   "intro.3": "Vous glissez votre carnet dans votre sac et respirez profondément.",
   "intro.3a": "Prendre le sac et partir",
   "intro.4": "Le trajet jusqu'à la clinique est court. Vous repassez tout dans votre tête : écouter avant d'étiqueter, soutenir avant de conseiller.",
   "intro.5": "Une bonne prise en charge commence par le lien. Un diagnostic précipité éloigne le patient.",
   "intro.6": "L'enseigne indique Clinique NeuroClin. Vous sortez la clé de votre sac.",
   "intro.6a": "Ouvrir la porte",
   "intro.7": "Voici votre cabinet. Chaque séance dure 50 minutes. Au fil de la semaine, vous pourrez le décorer et l'agrandir avec les pièces gagnées.",
   "intro.8": "Deux choses vous aideront : le dossier du patient, qui se remplit au fil de vos découvertes, et le Manuel diagnostique, avec critères et approches.",
   "intro.9": "Toc, toc... Quelqu'un est à la porte. C'est {nome}, le premier rendez-vous de la journée.",
   "intro.9b": "Ouvrir la porte au patient ▶",
   "intro.next": "Continuer ▶",
   "intro.skip": "Passer l'intro ▶▶",
   "lang.gn.note": "Guarani : traduction faite sans relecture d'un locuteur natif. Si vous parlez guarani, vos corrections sont les bienvenues !",
