   "opt.amb": "Ambience",
   "consult.listen.body": "Name what the body says",
   "consult.listen.body.hint": "The speech comes with a gesture. Naming what you see, without accusing, welcomes and opens a door. Costs {n} min of the session, and {max} fit per session.",
   "consult.fim.nota": "End of session · {n} min of talk",
   "consult.fim.ok": "Close",
   "consult.pico": "Respond to what just happened",
   "consult.pico.hint": "The person has reached their limit. What you answer now comes from somewhere in you — choose where. Takes {n} min.",
   "consult.pico.sem": "The person has reached their limit and you have no Wheel axis developed enough to answer. The moment will pass.",
   "consult.pico.pergunta": "Where do you answer from?",
   "consult.pico.nivel": "level",
   "consult.contra": "What went through your head",
   "consult.contra.name": "Name what is yours",
   "consult.contra.name.hint": "That thought is about you, not the person in front of you. Recognising it gives your place back — takes {n} min.",
   "consult.contra.act": "Go with that impulse",
   "consult.contra.act.hint": "It looks like the obvious way out. It is quick, costs no time — and the bill lands on the bond.",
   "consult.listen.confront": "Present a finding",
   "consult.listen.confront.hint": "Your chart already holds what contradicts what the family believes. Presenting it needs bond — and costs {n} min.",
   "tut.bubble.x": "{nome} is your first patient. Read carefully what is said in the bubble: every line holds clues about what lies behind the complaint. The portrait beside it says whose voice it is — when someone comes along, it changes with whoever is speaking.",
   "fu.toast.naoquer": "💬 {name} wrote: for now, they do not want to continue in therapy.",
   "week.bal.titulo": "What these weeks left behind",
   "week.bal.resumo": "{n} seen · {f} case(s) closed · {a} correct diagnosis(es) · {t} in therapy",
