   "help.l1": "<strong>Rembiapoukapy (Ψ):</strong> ohechauka ára sesionkuéra. Eikutu peteĩ tarjeta ehecha hag̃ua kaso ha <em>Emoñepyrũ sesión</em> (térã okẽ) eñepyrũ hag̃ua.",
   "help.l2": "<strong>Mbohovái:</strong> sapy'a opción ha'e peteĩ <strong>abordaje</strong> iñambuéva (apoyo, TCC, psicodinámico...). Iporã maymáva hendápe paciente problema rehe. Jeporavo porã omoi'a <strong>Jerovia</strong> ha ome'ẽ <strong>XP</strong>.",
   "help.l3": "<strong>Kuatiapyre:</strong> oñongatu ojejuhúva. Ojehe'i porã eporandu porã vove.",
   "help.l4": "<strong>Manual:</strong> oguereko trastorno aty, criterios ha abordaje. Reñemo'ã ramo, eme'ẽ pirapire ehecha hag̃ua kaso aty.",
   "help.l5": "<strong>Mbarete ha pytu'u:</strong> opa sesión ombyasy. Sesión pa'ũme oĩ pytu'u: eipuru umi mba'e sala-pe ejuhu jey hag̃ua.",
   "help.l6": "<strong>Pirapire ha tienda:</strong> sesión rire reganhá pirapire, oñemu hag̃ua ñemoiporã, konsultório ha róga ñemoiporã ha ao.",
   "help.l7": "<strong>Teclado:</strong> sesión aja eipuru <kbd>A</kbd> <kbd>B</kbd> <kbd>C</kbd> <kbd>D</kbd> (térã <kbd>1</kbd> guive <kbd>4</kbd>-peve) emohovái hag̃ua.",
   "help.l8": "<strong>Táva ha celular:</strong> eguata táva-pe (mapa ícono), eñemongeta tapichakuéra ndive ha eñangareko tienda ára-pe. Sapy'a paciente ojevy 4 arapokõindy pukukue; pedido de terapia oúva celular-pe.",
   "help.l9": "<strong>Índice del juego:</strong> pantalla ñepyrũme, 🧭 botón ohechauka opa sistema (mar, casino, obra, angirũ, purahéi, logro…) ha moõpa ojejuhu.",
   "help.replay": "↺ Eñepyrũ jey tutorial pytyvõ",
