   "idx.live.t": "Táva oikovéva",
   "idx.live.x": "Tapichakuéra oguata rutina ndive, tienda oñeñuã ha oñemboty, ka'aru rire tape ipytũ. Eñemongeta ndaha'éiva paciente ndive: eñemomba'e rire, ojejapo terapia arapokõindy oúvape.",
   "idx.manual.t": "Manual diagnóstico",
