   "idx.mind.t": "Ludoteca de la Mente (minijuego)",
   "idx.mind.x": "Tape guasúpe: 10 juego test añete rehegua (Schulte, Trazado, Stroop, dígito, Simon, Corsi, Go/No-Go, 1-back, emoción ha respiración). Peteĩteĩ omoñe'ẽ mba'épa omboguata; premio ára pegua ojehupyty peteĩha partida-pe.",
   "idx.music.t": "Purahéi ha instrumento",
   "idx.music.x": "Jeporavo-pe, eiporavo instrumento banda sonora-pe (campana, piano, flauta térã arpa). Sapy'a personaje oguereko tema ñemongeta-pe ha sapy'a paciente oguereko itono sesión-pe.",
   "idx.npc.t": "Angirũ",
