   "intro.1": "Segunda-feira, 6:45 pyharevete. Pe relõ ndoñemongu'éi. Koʼãga ha'e nde ára ñepyrũ neuroevaluación clínica-pe.",
   "intro.10": "{nome}: 'Mba'éichapa... ko'ápa heta ajerure? Aiko sa'i nerviosa.'",
   "intro.10b": "Emoñepyrũ sesión ▶",
   "intro.10v2": "{nome}: 'Mba'éichapa ne ka'aru... ko'ápa aju? Aiko sa'i ansiosa.'",
   "intro.10v3": "{nome}: '(ijyvate) Mba'éichapa... amba'e cita koʼãga. Ehejami, ha'e che ñepyrũ terapia-pe.'",
   "intro.1a": "Emboguejy alarma",
   "intro.2": "Reho mboyve, ehecha sa'i nde celular: recepción heja peteĩ marandu.",
   "intro.2a": "Ehecha marandu",
   "intro.2from": "Clínica recepción",
   "intro.2msg": "Mba'éichapa ne pyhare, {doc}! Koʼãga: Maria 8:00-pe ha Lucas 9:00-pe. Umi kuatiapyre oĩma konsultório-pe.",
   "intro.3": "Emoĩ nde cuaderno nde bolsa-pe ha reñemboyku porã.",
   "intro.3a": "Egueru bolsa ha eho",
   "intro.4": "Clínica-pe tape mbykymi. Reikuaa'i nde akã-pe: ñahendu raẽ ñamoĩ mboyve etiqueta, ñamoirũ raẽ ñamoĩ mboyve consejo.",
   "intro.5": "Ñeñangareko porã oñepyrũ jerovia rehegua. Diagnóstico pya'e ombogue paciente.",
   "intro.6": "Pe letrero he'i NeuroClin Clínica. Reipe'a llave nde bolsa-gui.",
   "intro.6a": "Embojere okẽ",
   "intro.7": "Ko'ã ha'e nde konsultório. Sapy'a sesión oiko 50 aravo. Semana aja ikatu remoiporã ha remoakãrapu'ã reganhá pirapirépe.",
   "intro.8": "Mokõi mba'e oipytyvõta: paciente kuatiapyre, oñemyenyhẽva rejuhu vove, ha Manual Diagnóstico, criterios ha abordaje ndive.",
   "intro.9": "Toc, toc... Oĩ okẽme. Ha'e {nome}, ára ñepyrũrã.",
   "intro.9b": "Embojere okẽ paciente-pe ▶",
