   "intro.skip": "Emboyke introdución ▶▶",
   "lang.gn.note": "Avañe'ẽ: ñemboguata ndojehecha'ỹ avañe'ẽ ñe'ẽhára. Reñe'ẽ ramo avañe'ẽ, nde rembiapo porã ojerurekuévo!",
