   "tip.energia.t": "⚡ Mbarete",
   "tip.energia.x": "Sapy'a sesión ombyasy. Mbarete michĩ ramo nde mbohovái ohepyme'ẽ mbovyve. Pytu'u pukukue reipurũ umi mba'e sala-pe ejuhu jey hag̃ua.",
   "tip.fala.t": "👂 Ehendu paciente",
   "tip.fala.x": "Emoñe'ẽ porã pe globo ñe'ẽme: oguereko marandu mba'épa oĩ ñemyesakã rapykuéri.",
   "tip.ficha.t": "📋 Kuatiapyre pyahu",
   "tip.ficha.x": "Pe kuarahyresa pytã ohechauka ojejuhu vove mba'e pyahu paciente rehegua. Eikutu kuatiapyre ehecha hag̃ua.",
   "tip.investigar.t": "🔎 Porandu",
   "tip.investigar.x": "Eiklike ápe eporandu hag̃ua pyahẽ, ke, mba'épa oikovaekue, mba'e vai ha ambue mba'e rehe. Peteĩ-teĩ mba'e he'íva ojehecha porãta ficha-pe ha diagnóstico-pe g̃uarã.",
   "tip.manual.t": "📖 Manual diagnóstico",
   "tip.manual.x": "Reikotevẽ recheka criterios térã abordaje? Eipe'a manual. Nderejuhúi ramo kaso aty, eme'ẽ {n} pirapire peteĩ pytyvõrã.",
   "tip.moedas.t": "🪙 Reganhá pirapire!",
   "tip.moedas.x": "Eipuru tienda-pe (bolsa yvate) emopotĩ hag̃ua konsultório, nde róga ha nde ao.",
   "tip.opcoes.t": "🎯 Eiporavo peteĩ abordaje",
   "tip.opcoes.x": "Sapy'a mbohovái ha'e peteĩ abordaje iñambuéva (apoyo, TCC...). Iporã maymáva hendápe paciente problema rehe. Ikatu avei eipuru A, B, C ha D tecla.",
   "tip.porta.t": "🚪 Sesión oúva",
   "tip.porta.x": "Pe okẽ omoñepyrũ sesión oúva rembiapoukapýpe. Pe Ψ nemoĩ jey ko kuatiápe.",
   "tip.vinculo.t": "💖 Jerovia",
   "tip.vinculo.x": "Ko barra ohechauka paciente jerovia (0-gui 100%-peve). Umi abordaje oĩva kasopy omoi'a jerovia; umi ndoikóiva ha jejuzga omboguejy. Ipahápe, jerovia ha mbyja oiko pirapire.",
   "tips.again": "✓ Pytyvõ oñemoingove jey",
