   "town.convince": "Emoĩ eha'ã terapia",
   "town.convince.help": "Eiporavo pe argumento oĩva tapicha-pe. Peteĩ ha'ãgui ára-pe añoite; umi hasyvéva oikotevẽ jerovia raẽ (eñemongeta hendive ára iñambuéva-pe).",
   "town.convince.title": "Emoĩ {name}",
   "town.convinced": "{name} ko'ágã oguereko terapia nde ndive. Aguyje reñemoĩ haguére!",
   "town.diagnose": "Diagnosticar",
   "town.legend": "🩺 paciente · ❔ vecino · ⭐ especial · 💚 ojerovia",
   "town.patient": "Mba'éichapa, doctora! Aiko seguimiento-pe: {n} {total}-gui sesión. Evolución ko'ágã peve: {p}%.",
   "town.patient.new": "Mba'éichapa! Ñañemoñe'ẽ gueteri porã. Aju koʼã mba'e rehe: {complaint}",
   "town.result.almost": "{name} omoĩ ñemo'ã... sa'imi! Ambue argumento ikatu.",
   "town.result.no": "{name} ndojerovia'ỹ ko argumento-pe.",
   "town.result.trust": "{name} ohayhu pe argumento, ha katu ndojerovia gueteri nderehe. Eñemongeta ambue ára-pe ha eha'ã jey.",
   "town.result.yes": "{name} oĩ porã!",
   "town.result.yes.last": "Ko ha'e pe semana ipaha, ndaipóri tenda sesión-pe, ha katu ha'e peteĩ ñepyrũ porã (+8 XP, +10 pirapire).",
   "town.result.yes.next": "Peteĩ sesión oñemoĩ semana oúvape (+8 XP, +10 pirapire).",
   "town.special.halloween": "Konsultório ohupyty calabaza ha purahéi kuéra rehegua! 🎃",
   "town.special.natal": "Konsultório ohupyty ñemoiporã ha purahéi Navidad rehegua! 🎄",
   "town.special.pascoa": "Konsultório ohupyty ovo Pascua ha purahéi ka'aguy rehegua! 🐰",
   "town.tried": "Reha'ãma reñemoĩ {name} ko árape. Eju ko'ẽrõ.",
   "travel.home": "Reho jey konsultório-pe…",
   "travel.house": "Reho róga-pe…",
   "tut.appx1.t": "Paciente apéndice",
   "tut.appx1.x": "Ehecha mávapa ojehecha, mávapa oúva, mba'e etapa sesión-pe ha nde hipótesis diagnóstico oĩ porã-ta.",
   "tut.appx2.t": "Ñembosarai índice",
   "tut.appx2.x": "Reñemo'ã ramo, índice oñemoĩ opa ikatúva rejapo ñembosarai-pe ha moõpa ojejuhu.",
   "tut.break1.t": "Eñangareko nderehe pytu'u aja",
   "tut.break1.x": "Eikutu mba'e sala-pe térã botón: psicóloga oho ha ojapo pe acción, ojuhu jey mbarete. Reguereko sa'i acción añoite.",
   "tut.bubble.t": "Ehendu paciente",
   "tut.choices.t": "Eiporavo mba'e ere",
   "tut.choices.x": "Sapy'a opción ha'e peteĩ abordaje iñambuéva. Ko sesión ñepyrũme oñemoĩ téra; upe rire opa ha nde reiporavo nde rekove. Eikutu peteĩ opción emohovái hag̃ua.",
   "tut.city1.t": "Ehecha ryepýpe",
   "tut.city1.x": "Ko'ágã ikatu reguata tenda-pe: WASD térã flecha computadora-pe, joystick celular-pe, térã eikutu yvýre pe personaje oho hag̃ua. Eikutu peteĩ okẽ, mba'e térã tapicha-pe eho ha eñemongeta.",
   "tut.city2.t": "Minimapa",
   "tut.city2.x": "Minimapa ohechauka nde (mba'e pytãngy), umi mba'e tuichaitéva (sa'yju) ha esẽ mapa-pe (naranja).",
   "tut.city3.t": "Eho jey mapa-pe",
   "tut.city3.x": "Eikutu ko'ápe eipe'a hag̃ua mapa ha eho ambue tendápe. Ikatu avei resẽ sapy'a tenda 🚪 okẽ-gui.",
   "tut.dayend1.t": "Relõ ha pyhare",
   "tut.dayend1.x": "Rembiapo ára opáma, ha katu ára oku'ejey. Ehecha relõ: tienda oguereko aravo ojepe'a ha oñemboty pyhare, ha táva ojepytaso. Gasolinera opytáma 24 aravo.",
   "tut.dayend2.t": "Eguata ha eke",
   "tut.dayend2.x": "Eipuru táva botón reguata hag̃ua: eguata WASD, flecha térã joystick ndive ha eike tenda-pe. Emohu'ã vove ára, eho departamento-pe ha eke ke-pe: upéicha añoite oñepyrũ ára oúva.",
   "tut.decor1.t": "Kuarto planta",
   "tut.decor1.x": "Eguenoha peteĩteĩ mueble planta-pe moõpa reipota. Oikutu ramo ambue-pe, okatu kuartogui térã omboty tape, juego ohechakuaa ha ndoheja.",
   "tut.decor2.t": "Emoĩ ha emoĩ jey",
   "tut.decor2.x": "Eikutu peteĩ mueble ha eipuru Emoĩ (térã R). \"Tenda ypykue\" ogueru jey. Kuarto guasu tienda de decoración-pe oguereko hetave tenda.",
   "tut.dx.t": "Hipótesis diagnóstico",
   "tut.dx.x": "Sapy'a paciente sesión ipahápe (4ª), reiporavo hipótesis iporãvéva opa reñehendúva ndive. Rehupyty ramo, reganhá peteĩ mbyja ha experiencia. Upéi oúta pe derivación.",
   "tut.fauna1.t": "Mymba michĩ táva-pe",
   "tut.fauna1.x": "Aguara'i, guyra, panambi, jagua ha pira oiko ápe. Oñemondýi eipotave ramo, eguata mbegue ehecha haguã.",
   "tut.feedback.t": "Mba'e ojapo pe ere",
   "tut.feedback.x": "Ko'ápe rehecha mba'e abordaje reipuru, oikó térã nahániri ha mba'ére. Peteĩ ñe'ẽ ikatu iporã peteĩ paciente ndive ha ivai ambue-pe.",
   "tut.ficha.t": "Kuatiapyre",
   "tut.ficha.x": "Ko'ápe ojehecha reikuaáva. Oñepyrũ ndaha'evai ha oñemyenyhẽ eporandu porã rupi.",
   "tut.fu.t": "Seguimiento",
   "tut.fu.x": "Sapy'a paciente ou jey 4 jey, mokõi semana-pe. Diagnóstico ha derivación oúva 4ª sesión-pe añoite, ha upéi paciente ikatu ojerure oku'ejey hag̃ua terapia. Pe jerure oguahẽ nde celular-pe.",
   "tut.hint": "Eikutu pe área hesakãva",
   "tut.manual.t": "Manual diagnóstico",
   "tut.manual.x": "Nde consulta pya'e: trastorno, criterios ha abordaje terapéutico. Eipe'a rejepy'apy vove, avei eiporavo aja hipótesis ipaha.",
   "tut.map1.t": "Táva mapa",
   "tut.map1.x": "Ko'ápe reiporavo moõ reho. Táva oguereko área: tape guasu (clínica, departamento ha tienda, reguata hendápe), pe ypa'ũ, plaza ha paciente barrio.",
   "tut.map2.t": "Eguata mapa-pe",
   "tut.map2.x": "Eipuru flecha, WASD térã joystick ereguata hag̃ua kure'ỹ peteĩ tenda-pe ha eikutu Enter (térã eikutu E). Ikatu avei eikutu tenda-pe.",
   "tut.map3.t": "Ehecha relõ",
   "tut.map3.x": "Sapy'a viaje ogueraha 15 minuto. Reju hemby sesión-pe omoĩ jerovia, upévare ehecha tapiaite aravo.",
   "tut.mind1.t": "Ludoteca de la Mente",
   "tut.mind1.x": "Eñemboja'o peteĩ juego-pe ha eikutu botón de acción. Peteĩteĩ minijuego test añete rehegua ha ipahápe omoñe'ẽ mba'épa omboguata.",
   "tut.next": "Eku'ejey ▶",
   "tut.npc1.t": "Ñemongeta ojapo angirũ",
   "tut.npc1.x": "Eñemongeta peteĩ tapicha ndive ára iñambuéva. Mbohapy ñemongeta rire, oiko angirũ ha oñepyrũ ome'ẽ jopói.",
   "tut.opts1.t": "Opciones: eiko ndeguarã",
   "tut.opts1.x": "Ápe ikatu embojoja ñe'ẽ, letra ha tamaño, tema hesakã/ypytũ, ryrýi ha purahéi, modo optimizado ha actividades interactivas. Ikatu emoambue oimeraẽ ára.",
   "tut.pets1.t": "Nde mascota",
   "tut.pets1.x": "Eñangareko nde mascota rehe sapy'a ára: emongaru, eñembosarai ha emomirĩ omoi'a jerovia. Oñangarekóva porã, oipytyvõ sesión-pe.",
   "tut.phone1.t": "Celular marandu",
   "tut.phone1.x": "Marandu paciente oúva rehegua oguahẽ ko'ápe, ára ha aravo ndive. Emoñe'ẽ sesión mboyve: oĩ techapyrã.",
   "tut.shop1.t": "Ñemu tienda-pe añoite",
   "tut.shop1.x": "Rógape ikatu rehecha ha reipuru nde mba'e añoite. Remu hag̃ua eho tienda oĩva mapa-pe. Mba'e oñemboty ohechauka moõ ojejuhu.",
   "tut.skip": "Emboyke tutorial",
   "tut.souv1.t": "Pin ha accesorio",
   "tut.souv1.x": "Ko'ápe reiporavo bandera, causa, lente ha joya. Pe remuva ojehecha nde personaje-pe hi'ári.",
   "tut.station1.t": "Mba'e ha okẽ",
   "tut.station1.x": "Reñemoag̃ui vove peteĩ mba'e ikatúva reipuru, ko botón ojehecha hérape rehegua. Eikutu térã eikutu E.",
   "tut.street1.t": "Tape guasu",
   "tut.street1.x": "Eguata tape rehe ha emoag̃ui peteĩ edificio okẽ-pe (térã eikutu hese) ha eikutu E eike hag̃ua. Letrero ohechauka aravo ojepe'a: tienda oñembotýva ojepytasova candado ndive. Resẽ vove, reju jey pe okẽ peteĩ-pe.",
   "tut.uni1.t": "Universidad clase",
   "tut.uni1.x": "Eiporavo peteĩ clase, emoñe'ẽ Manual criterios, upéi ejapo quiz. Ñepyrũ aprobar ome'ẽ experiencia ha pirapire; jejavy ohechauka mbohovái porã.",
   "tut.vinculo.t": "Jerovia ha mbarete",
   "tut.vinculo.x": "Jerovia ohechauka mboy'ápa paciente ndeʼerovia ha opu'ã jeporavo porã rupi. Mbarete omboguejy sapy'a sesión; eñangareko pytu'u aja.",
   "uni.again": "Ambue porandu",
   "uni.diploma": "🎓 Reaprobá opa clase! Diploma pukukue.",
   "uni.exam": "Ejapo quiz",
   "uni.examof": "Quiz",
   "uni.failed": "Ndajaikoveíri. Rehupyty {r} {n}-gui; emoñe'ẽ jey clase ha eha'ã jey.",
