   "fu.txwhy.grupo": "Adatto all'uso problematico di alcol e altre sostanze: servizi specializzati e gruppi di sostegno sostengono il cambiamento.",
   "fu.txwhy.psico": "Adatto quando il quadro risponde bene alla psicoterapia e non ci sono segni di rischio né sintomi che richiedano una valutazione medica.",
   "fu.txwhy.psicpsiq": "Adatto quando i sintomi sono intensi, la compromissione è grande o c'è rischio: lo psichiatra valuta se serve un farmaco. Prescrive il medico, mai lo psicologo.",
   "fu.type.1": "1ª seduta: colloquio iniziale",
   "fu.type.2": "2ª seduta: approfondimento",
   "fu.type.3": "3ª seduta: andamento",
   "fu.type.4": "4ª seduta: restituzione e invio",
   "fu.week": "Settimana {w} di {t}",
   "fu.weekroll": "Settimana {n} conclusa! Lunedì inizia la settimana {m}. I pazienti in terapia con te hanno fruttato {c} monete.",
   "guide.count": "Scoperti: {n} su {t}",
   "guide.help": "Gli animali che vivono in città, sulla spiaggia e nel mare. Cammina vicino a ciascuno per scoprirlo; quelli non ancora visti compaiono come ombra.",
   "guide.hint": "Non ancora visto. Cerca in:",
   "guide.title": "🦋 Guida alla fauna",
   "guide.unknown": "???",
   "guide.where": "Dove vive",
   "hair.afro": "Afro",
   "hair.bob": "Caschetto mosso",
   "hair.braids": "Trecce",
   "hair.bun": "Chignon",
   "hair.buzz": "Rasati",
   "hair.curly": "Ricci",
   "hair.long": "Lunghi",
   "hair.pixie": "Taglio pixie",
   "hair.ponytail": "Coda di cavallo",
   "hair.short": "Corti",
   "hair.wavy": "Mossi",
   "help.intro": "Sei un/una {prof} agli inizi. Ogni giorno, ricevi i pazienti in agenda e costruisci un legame con loro.",
   "help.l1": "<strong>Agenda (Ψ):</strong> mostra le sedute del giorno. Tocca una scheda per vedere il caso e <em>Inizia la seduta</em> (o la porta) per cominciare.",
   "help.l2": "<strong>Rispondere:</strong> ogni opzione è un <strong>approccio</strong> diverso (di sostegno, CBT, psicodinamico...). Funziona più o meno bene a seconda del problema del paziente. Le buone scelte aumentano il <strong>Legame</strong> e danno <strong>XP</strong>.",
   "help.l3": "<strong>Scheda:</strong> conserva ciò che hai scoperto. Si compila solo se fai buone domande.",
   "help.l4": "<strong>Manuale:</strong> contiene i gruppi di disturbi, i loro criteri e gli approcci. Se sei in difficoltà, paga monete per vedere il gruppo del caso.",
   "help.l5": "<strong>Energia e pause:</strong> ogni seduta stanca. Tra una seduta e l'altra c'è una pausa: interagisci con gli oggetti della stanza per recuperare.",
   "help.l6": "<strong>Monete e negozio:</strong> dopo ogni seduta guadagni monete, con cui compri decorazioni, ampliamenti di studio e casa e vestiti.",
   "help.l7": "<strong>Tastiera:</strong> durante una seduta usa i tasti <kbd>A</kbd> <kbd>B</kbd> <kbd>C</kbd> <kbd>D</kbd> (o da <kbd>1</kbd> a <kbd>4</kbd>) per rispondere.",
   "help.l8": "<strong>Città e telefono:</strong> gira per la città (icona della mappa), parla con i residenti e controlla gli orari dei negozi. Ogni paziente torna nell'arco di 4 settimane; le richieste di terapia arrivano sul telefono.",
   "help.l9": "<strong>Indice del gioco:</strong> nella schermata iniziale, il pulsante 🧭 elenca ogni sistema (mare, casinò, lavori, amici, musica, traguardi…) e dove trovarlo.",
   "help.replay": "↺ Rivedi i suggerimenti del tutorial",
   "help.title": "Come si gioca",
