   "hud.coins": "Monete",
   "hud.day": "Giorno",
   "hud.defesa": "Difesa",
   "hud.defesa.info": "Quanto la persona si sta ancora proteggendo. Più è alta, meno racconta, e le aree delicate restano chiuse. Cala quando il legame cresce.",
   "hud.energy": "Energia",
   "hud.level": "Livello",
