   "hud.vinculo": "Legame",
   "hud.week": "Settimana {n}/{t}",
   "hud.weekend": "Weekend",
   "idx.ach.t": "Traguardi e Guardiani",
   "idx.ach.x": "Completa le sfide per ottenere traguardi. Trova i sei Guardiani in giro per la città per completare La Leggenda dei Guardiani.",
   "idx.appx.t": "Appendice e agenda",
   "idx.appx.x": "Vedi chi è stato visto, chi è il prossimo e il riepilogo della settimana.",
   "idx.break.t": "Pausa tra le sedute",
   "idx.break.x": "Dieci minuti per prenderti cura di te: tocca gli oggetti della stanza e recupera energia.",
   "idx.city.t": "Passeggia per la città",
   "idx.city.x": "Icona 🗺️: cammina con WASD o il joystick. Scopri luoghi, chiacchiera e tieni d'occhio l'orario della prossima seduta.",
   "idx.cloud.t": "Account e classifica",
   "idx.cloud.x": "Con il server attivo: sincronizza tra dispositivi e confronta i punti.",
   "idx.consult.t": "Sedute con i pazienti",
   "idx.consult.x": "Ogni seduta ha 4 o 5 passi di conversazione. Scegli l'approccio più adatto alla persona e al momento.",
   "idx.culture.t": "Centro commerciale, lingue e storia",
   "idx.culture.x": "Al centro commerciale cambia la lingua del gioco nel negozio di lingue (guaraní incluso) e leggi la storia della psicologia.",
   "idx.decor.t": "Casa e studio",
   "idx.decor.x": "Arreda e amplia studio, sala d'attesa e cucina nel negozio.",
   "idx.dress.t": "Personalizzazione e camerino",
   "idx.dress.x": "Cambia viso, capelli e vestiti quando vuoi. Prova gli articoli nel camerino prima di comprare.",
   "idx.dx.t": "Ipotesi diagnostica",
   "idx.dx.x": "Alla fine di ogni seduta, scegli l'ipotesi più coerente. Azzeccarla vale una stella in più.",
   "idx.fauna.t": "Guida alla fauna",
   "idx.fauna.x": "Ogni animale della città, della spiaggia e del mare, con dove vive e una curiosità. Scoprili camminando vicino.",
   "idx.follow.t": "Follow-up in 4 sedute",
   "idx.follow.x": "Ogni paziente torna nell'arco di 4 settimane. La diagnosi si stabilisce solo alla 4ª seduta; nel frattempo rispondi alle richieste di terapia sul telefono.",
   "idx.help": "Tutto ciò che puoi fare, e dove.",
   "idx.leisure.t": "Palestra, mercato, tavola calda e casinò",
   "idx.leisure.x": "Cura la tua energia e il tuo umore, fai acquisti e goditi i minigiochi del casinò (senza esagerare!).",
   "idx.live.t": "Città viva",
   "idx.live.x": "I residenti seguono delle routine, i negozi aprono e chiudono e la strada si fa buia di notte. Parla con chi non è paziente: se lo convinci, prenoterà la terapia la settimana successiva.",
   "idx.manual.t": "Manuale diagnostico",
   "idx.manual.x": "Criteri di decine di disturbi e gli approcci. Aprilo durante una seduta ogni volta che hai dubbi.",
   "idx.mind.t": "Ludoteca della Mente (minigiochi)",
   "idx.mind.x": "Sulla via principale: 10 giochi basati su test reali (Schulte, Trail Making, Stroop, span di cifre, Simon, Corsi, Go/No-Go, 1-back, coppie di emozioni e respirazione). Ognuno spiega cosa allena; il premio giornaliero arriva alla prima partita.",
   "idx.music.t": "Musica e strumenti",
   "idx.music.x": "Nelle Opzioni scegli lo strumento della colonna sonora (campanelli, pianoforte, flauto o arpa). Ogni personaggio ha un tema mentre parla e ogni paziente ha un proprio tono in seduta.",
   "idx.npc.t": "Amicizie",
   "idx.npc.x": "Parla con le persone in città in giorni diversi. Gli amici fanno regali.",
   "idx.opts.t": "Opzioni",
   "idx.opts.x": "Lingua, audio, 3D, suggerimenti e modalità di apprendimento, che mostra gli approcci.",
   "idx.pets.t": "Animali",
   "idx.pets.x": "Adotta animali comuni o esotici. Prenditi cura di loro: aiutano nelle sedute e ti seguono in città.",
   "idx.phone.t": "Telefono",
   "idx.phone.x": "Messaggi dei pazienti con il giorno e l'ora di arrivo.",
   "idx.sea.t": "Mare, navi e acquario",
   "idx.sea.x": "Dalla spiaggia, rema fino alla nave pirata, all'Olandese Volante (solo di notte) e alla fenditura sottomarina. Convinci i residenti e raccogli creature per l'acquario.",
   "idx.secret.t": "Modalità segreta",
   "idx.secret.x": "Visitatori delle feste nel menu del titolo.",
   "idx.shop.t": "Negozi e abiti",
   "idx.shop.x": "Negozio di abbigliamento e boutique (pezzi esclusivi) per vestire il tuo personaggio.",
   "idx.souv.t": "Souvenir e spille",
   "idx.souv.x": "Bandiere, cause e movimenti, occhiali e bigiotteria da indossare.",
   "idx.title": "🧭 Indice del gioco",
   "idx.uni.t": "Università",
   "idx.uni.x": "Rispondi a domande sui criteri del Manuale e guadagna esperienza e denaro.",
   "idx.wheel.t": "Ruota dello psicologo",
   "idx.wheel.x": "Il tuo profilo dominante dà un vantaggio in certe conversazioni. Dopo una buona risposta può comparire un dialogo extra.",
   "idx.works.t": "Lavori, amici e rete di sostegno",
   "idx.works.x": "Amplia l'appartamento e la clinica nelle postazioni dei lavori. Nella scheda Amici del telefono organizza caffè: ogni 3 amici stretti ti danno +1 energia al risveglio.",
   "info.age": "Età",
   "info.complaint": "Motivo della visita",
   "info.name": "Nome",
   "info.type": "Tipo",
   "instr.bell": "Campanelli",
   "instr.flute": "Flauto",
   "instr.harp": "Arpa",
   "instr.piano": "Pianoforte",
   "intro.1": "Lunedì, ore 6:45. La sveglia non smette di suonare. Oggi è il tuo primo giorno alla clinica di neurovalutazione.",
   "intro.10": "{nome}: «Salve... è qui che ho prenotato? Sono un po' agitata.»",
   "intro.10b": "Inizia la seduta ▶",
   "intro.10v2": "{nome}: «Buon pomeriggio... sono venuta nel posto giusto? Sono un po' ansiosa.»",
   "intro.10v3": "{nome}: «(piano) Salve... ho un appuntamento adesso. Scusi, è la mia prima volta in terapia.»",
   "intro.1a": "Spegni la sveglia",
   "intro.2": "Prima di uscire, un'occhiata al telefono: la reception ha lasciato un messaggio.",
   "intro.2a": "Vedi i messaggi",
   "intro.2from": "Reception della clinica",
   "intro.2msg": "Buongiorno, {doc}! Oggi: Maria alle 8:00 e Lucas alle 9:00. Le schede sono già nello studio.",
   "intro.3": "Metti il quaderno nella borsa e fai un respiro profondo.",
   "intro.3a": "Prendi la borsa ed esci",
   "intro.4": "La strada per la clinica è breve. Ripassi mentalmente: prima ascoltare, poi etichettare; prima sostenere, poi consigliare.",
   "intro.5": "Una buona cura inizia dal legame. Una diagnosi affrettata allontana il paziente.",
   "intro.6": "L'insegna dice Clinica NeuroClin. Tiri fuori la chiave dalla borsa.",
   "intro.6a": "Apri la porta",
   "intro.7": "Questo è il tuo studio. Ogni seduta dura 50 minuti. Durante la settimana puoi arredarlo e ampliarlo con le monete che guadagni.",
   "intro.8": "Due cose ti aiuteranno: la scheda del paziente, che si compila man mano che scopri le cose, e il Manuale diagnostico, con criteri e approcci.",
   "intro.9": "Toc, toc... Qualcuno è alla porta. È {nome}, il primo appuntamento della giornata.",
   "intro.9b": "Apri la porta al paziente ▶",
   "intro.next": "Continua ▶",
   "intro.skip": "Salta l'introduzione ▶▶",
   "lang.gn.note": "Guaraní: traduzione fatta senza la revisione di un madrelingua. Se parli guaraní, le tue correzioni sono molto benvenute!",
   "lang.label": "Lingua",
   "leave.confirm": "Uscire dalla seduta? I progressi di questa seduta andranno persi.",
   "legend.anam": "<strong>Colloquio iniziale</strong><br>Prima seduta: ascolto della lamentela e della storia di vita e di sviluppo.",
   "legend.dev": "<strong>Seduta di restituzione</strong><br>Consegna di risultati e relazione, con indicazioni per famiglia e scuola.",
   "legend.test": "<strong>Valutazione</strong><br>Somministrazione di strumenti e osservazione clinica, seguendo il protocollo standardizzato.",
   "legend.title": "Legenda dei pallini",
