   "tip.energia.t": "⚡ Energia",
   "tip.energia.x": "Ogni seduta stanca. Con poca energia le tue risposte contano meno. Durante la pausa, interagisci con gli oggetti della stanza per recuperare.",
   "tip.fala.t": "👂 Ascolta il paziente",
   "tip.fala.x": "Leggi con attenzione il fumetto: contiene indizi su ciò che c'è dietro la lamentela.",
   "tip.ficha.t": "📋 Scheda aggiornata",
   "tip.ficha.x": "Il puntino rosso ti avvisa quando scopri qualcosa di nuovo sul paziente. Tocca la scheda per vedere.",
   "tip.investigar.t": "🔎 Indagare",
   "tip.investigar.x": "Clicca qui per chiedere direttamente di umore, sonno, storia, rischi e altre aree. Ogni risposta diventa un indizio vero per la cartella e la diagnosi.",
   "tip.manual.t": "📖 Manuale diagnostico",
   "tip.manual.x": "Devi controllare criteri o approcci? Apri il manuale. Se non sei sicuro/a del gruppo del caso, paga {n} monete per un indizio.",
   "tip.moedas.t": "🪙 Hai guadagnato monete!",
   "tip.moedas.x": "Spendile nel negozio (la borsa in alto) per arredare lo studio, la casa e il tuo abbigliamento.",
   "tip.opcoes.t": "🎯 Scegli un approccio",
   "tip.opcoes.x": "Ogni risposta è un approccio diverso (di sostegno, CBT...). Funziona più o meno bene a seconda del problema del paziente. Puoi usare anche i tasti A, B, C e D.",
   "tip.porta.t": "🚪 Prossima seduta",
   "tip.porta.x": "La porta avvia la prossima seduta in agenda. La Ψ ti riporta sempre a questa pagina.",
   "tip.vinculo.t": "💖 Legame",
   "tip.vinculo.x": "Questa barra mostra la fiducia del paziente (da 0 a 100%). Gli approcci adatti al caso aumentano il legame; quelli inadatti e i giudizi lo abbassano. Alla fine legame e stelle diventano monete.",
   "tips.again": "✓ Suggerimenti riattivati",
