   "wheel.chip": "Profilo",
   "wheel.help": "Gli approcci che usi di più nelle sedute formano il tuo profilo. Il profilo dominante dà un vantaggio concreto e sblocca l'opzione di profilo (⭐) nelle conversazioni.",
