   "hair.bob": "ウェーブボブ",
   "help.intro": "あなたは駆け出しの{prof}です。毎日スケジュールの患者を診て、信頼関係を築きましょう。",
   "help.l1": "<strong>スケジュール（Ψ）：</strong>その日のセッションを表示します。カードをタップしてケースを確認し、<em>セッションを始める</em>（またはドア）で開始します。",
   "help.l2": "<strong>回答：</strong>各選択肢は異なる<strong>アプローチ</strong>（支持的、CBT、精神力動的など）です。患者の問題によって効き方が変わります。良い選択は<strong>信頼関係</strong>を高め、<strong>XP</strong>を与えます。",
   "help.l3": "<strong>カルテ：</strong>分かったことを記録します。良い質問をしたときだけ埋まります。",
   "help.l4": "<strong>マニュアル：</strong>障害のグループ、その基準、アプローチが載っています。迷ったらコインを払ってケースのグループを見られます。",
   "help.l5": "<strong>エネルギーと休憩：</strong>セッションはどれも疲れます。セッションの合間に休憩があり、部屋の物に触れて回復できます。",
   "help.l6": "<strong>コインとショップ：</strong>セッションごとにコインを獲得し、飾り、診療室や自宅の拡張、服を買えます。",
   "help.l7": "<strong>キーボード：</strong>セッション中は<kbd>A</kbd> <kbd>B</kbd> <kbd>C</kbd> <kbd>D</kbd>（または<kbd>1</kbd>〜<kbd>4</kbd>）キーで回答できます。",
   "help.l8": "<strong>街とスマホ：</strong>マップのアイコンから街を歩き、住人と話し、店の営業時間に気を配りましょう。患者は4週間通院し、相談依頼はスマホに届きます。",
   "help.l9": "<strong>ゲーム案内：</strong>ホーム画面の🧭ボタンで、すべてのしくみ（海・カジノ・増築・友だち・音楽・実績など）と場所を確認できます。",
