   "fu.txwhy.familia": "아동·청소년에게는 환경도 치료의 일부입니다. 가족과 학교를 안내하는 것이 치료만큼 중요할 때가 많습니다.",
   "fu.txwhy.grupo": "알코올과 다른 물질의 문제적 사용에 적합합니다. 전문 기관과 자조 모임이 변화를 지속하도록 돕습니다.",
   "fu.txwhy.psico": "심리치료에 잘 반응하고 위험 징후나 의학적 평가가 필요한 증상이 없을 때 적합합니다.",
   "fu.txwhy.psicpsiq": "증상이 심하거나 기능 저하가 크거나 위험이 있을 때 적합합니다. 정신건강의학과 의사가 약물이 필요한지 평가합니다. 처방은 의사가 하며 심리학자는 하지 않습니다.",
   "fu.type.1": "1회차: 초기 면담",
