   "guide.count": "발견: {t}마리 중 {n}마리",
   "guide.help": "도시, 해변, 바다에 사는 동물들입니다. 각 동물 가까이 걸어가 발견하세요. 아직 못 본 동물은 그림자로 나타납니다.",
