   "hair.short": "짧은 머리",
   "hair.wavy": "웨이브",
   "help.intro": "당신은 이제 막 시작한 {prof}입니다. 매일 일정에 있는 환자를 만나고 유대감을 쌓으세요.",
   "help.l1": "<strong>일정(Ψ):</strong> 그날의 상담을 보여 줍니다. 카드를 눌러 사례를 보고 <em>상담 시작</em>(또는 문)으로 시작하세요.",
   "help.l2": "<strong>답하기:</strong> 각 선택지는 서로 다른 <strong>접근법</strong>(지지적, CBT, 정신역동 등)입니다. 환자의 문제에 따라 효과가 다릅니다. 좋은 선택은 <strong>유대감</strong>을 높이고 <strong>경험치</strong>를 줍니다.",
   "help.l3": "<strong>차트:</strong> 알아낸 내용을 담습니다. 좋은 질문을 해야만 채워집니다.",
   "help.l4": "<strong>매뉴얼:</strong> 장애 그룹, 기준, 접근법이 들어 있습니다. 막막하면 코인을 내고 사례의 그룹을 확인하세요.",
   "help.l5": "<strong>에너지와 휴식:</strong> 상담은 매번 힘듭니다. 상담 사이 휴식 시간에 방 안의 물건과 상호작용해 회복하세요.",
   "help.l6": "<strong>코인과 상점:</strong> 상담이 끝날 때마다 코인을 얻고, 이 코인으로 장식, 진료실과 집 확장, 옷을 삽니다.",
   "help.l7": "<strong>키보드:</strong> 상담 중 <kbd>A</kbd> <kbd>B</kbd> <kbd>C</kbd> <kbd>D</kbd>(또는 <kbd>1</kbd>~<kbd>4</kbd>) 키로 답할 수 있습니다.",
   "help.l8": "<strong>도시와 휴대폰:</strong> 도시를 걸어 다니며(지도 아이콘) 주민과 대화하고 상점 영업시간을 확인하세요. 각 환자는 4주에 걸쳐 돌아오며 상담 요청은 휴대폰으로 옵니다.",
   "help.l9": "<strong>게임 색인:</strong> 홈 화면의 🧭 버튼이 모든 시스템(바다, 카지노, 리모델링, 친구, 음악, 업적…)과 위치를 보여 줍니다.",
