   "idx.ach.t": "업적과 수호자",
   "idx.ach.x": "도전을 완료해 업적을 얻으세요. 도시 곳곳의 수호자 여섯 명을 찾아 '수호자의 전설'을 완성하세요.",
   "idx.appx.t": "부록과 플래너",
   "idx.appx.x": "누가 상담을 받았고 누가 다음인지, 한 주 요약을 확인하세요.",
   "idx.break.t": "상담 사이 휴식",
   "idx.break.x": "10분 동안 스스로를 돌보세요. 방 안의 물건을 눌러 에너지를 회복합니다.",
   "idx.city.t": "도시 둘러보기",
   "idx.city.x": "🗺️ 아이콘: WASD 또는 조이스틱으로 걷습니다. 장소를 발견하고, 대화하고, 다음 상담 시간을 확인하세요.",
   "idx.cloud.t": "계정과 순위표",
