   "idx.consult.t": "환자와의 상담",
   "idx.consult.x": "각 상담은 4~5단계의 대화로 이루어집니다. 사람과 순간에 가장 잘 맞는 접근법을 고르세요.",
   "idx.culture.t": "쇼핑몰, 언어, 역사",
   "idx.culture.x": "쇼핑몰의 언어 가게에서 게임 언어를 바꾸고(과라니어 포함) 심리학의 역사를 읽어 보세요.",
   "idx.decor.t": "집과 진료실",
   "idx.decor.x": "상점에서 진료실, 대기실, 주방을 꾸미고 확장하세요.",
   "idx.dress.t": "꾸미기와 피팅룸",
   "idx.dress.x": "얼굴, 머리, 옷을 언제든 바꿀 수 있습니다. 사기 전에 피팅룸에서 입어 보세요.",
   "idx.dx.t": "진단 가설",
   "idx.dx.x": "각 상담이 끝나면 가장 일관된 가설을 고르세요. 맞히면 별을 하나 더 받습니다.",
   "idx.fauna.t": "야생동물 도감",
   "idx.fauna.x": "도시, 해변, 바다의 모든 동물과 서식지, 재미있는 사실. 가까이 걸어가서 발견하세요.",
   "idx.follow.t": "4회에 걸친 추적 관찰",
   "idx.follow.x": "각 환자는 4주에 걸쳐 돌아옵니다. 진단은 4회차에 확정됩니다. 그 사이에는 휴대폰의 상담 요청에 답하세요.",
   "idx.help": "할 수 있는 모든 것과 그 위치.",
   "idx.leisure.t": "헬스장, 시장, 식당, 카지노",
   "idx.leisure.x": "에너지와 기분을 돌보고, 쇼핑을 하고, 카지노 미니게임을 즐기세요(과하지 않게!).",
   "idx.live.t": "살아 있는 도시",
   "idx.live.x": "주민들은 일과에 따라 움직이고, 상점은 열고 닫고, 밤이 되면 거리가 어두워집니다. 환자가 아닌 사람들과 이야기해 보세요. 설득하면 다음 주에 상담을 예약합니다.",
   "idx.manual.t": "진단 매뉴얼",
   "idx.manual.x": "수십 가지 장애의 기준과 접근법이 있습니다. 확신이 없을 때 상담 중에 여세요.",
   "idx.mind.t": "마음 놀이방 (미니게임)",
   "idx.mind.x": "중심가에 있습니다. 실제 검사를 바탕으로 한 10개의 게임(슐테, 선 잇기, 스트룹, 숫자 폭, 사이먼, 코르시, Go/No-Go, 1-back, 감정 짝 맞추기, 호흡). 각각 무엇을 훈련하는지 설명하며, 매일의 보상은 첫 플레이에 주어집니다.",
   "idx.music.t": "음악과 악기",
   "idx.music.x": "설정에서 배경 음악 악기(종, 피아노, 플루트, 하프)를 고르세요. 캐릭터마다 대화 테마가 있고 환자마다 상담 중 고유한 음색이 있습니다.",
   "idx.npc.t": "우정",
   "idx.npc.x": "다른 날에 도시 사람들과 이야기하세요. 친구는 선물을 줍니다.",
   "idx.opts.t": "설정",
   "idx.opts.x": "언어, 소리, 3D, 팁, 그리고 접근법을 보여 주는 학습 모드.",
   "idx.pets.t": "반려동물",
   "idx.pets.x": "일반 또는 이색 반려동물을 입양하세요. 돌보면 상담에서 도움을 주고 도시에서 따라다닙니다.",
   "idx.phone.t": "휴대폰",
   "idx.phone.x": "도착한 날짜와 시간이 표시된 환자 메시지.",
   "idx.sea.t": "바다, 배, 수족관",
   "idx.sea.x": "해변에서 노를 저어 해적선, 유령선 플라잉 더치맨(밤에만), 해저 균열로 가세요. 주민을 설득하고 수족관에 넣을 생물을 모으세요.",
   "idx.secret.t": "비밀 모드",
   "idx.secret.x": "타이틀 메뉴에 있는 명절 손님들.",
   "idx.shop.t": "상점과 옷",
   "idx.shop.x": "캐릭터를 꾸미는 옷 가게와 부티크(한정 아이템).",
   "idx.souv.t": "기념품과 핀",
   "idx.souv.x": "착용할 수 있는 국기, 사회적 이슈와 운동, 안경, 장신구.",
   "idx.title": "🧭 게임 색인",
   "idx.uni.t": "대학교",
   "idx.uni.x": "매뉴얼 기준에 대한 문제에 답하고 경험치와 돈을 얻으세요.",
   "idx.wheel.t": "심리학자 휠",
   "idx.wheel.x": "우세한 프로필은 일부 대화에서 유리함을 줍니다. 좋은 답변 뒤에는 추가 대화가 나타날 수 있습니다.",
   "idx.works.t": "리모델링, 친구, 지지 네트워크",
   "idx.works.x": "리모델링 스테이션에서 아파트와 클리닉을 확장하세요. 휴대폰 친구 탭에서 커피 약속을 잡으면 가까운 친구 3명마다 기상 시 에너지 +1입니다.",
   "info.age": "나이",
   "info.complaint": "호소 문제",
   "info.name": "이름",
   "info.type": "유형",
   "instr.bell": "종",
   "instr.flute": "플루트",
   "instr.harp": "하프",
   "instr.piano": "피아노",
   "intro.1": "월요일 오전 6시 45분. 알람이 멈추지 않습니다. 오늘은 신경심리평가 클리닉에서의 첫날입니다.",
   "intro.10": "{nome}: 마리아: '안녕하세요... 여기가 예약한 곳 맞나요? 조금 긴장돼서요.'",
   "intro.10b": "상담 시작 ▶",
   "intro.10v2": "{nome}: 마리아: '안녕하세요... 제대로 찾아온 건가요? 조금 불안하네요.'",
   "intro.10v3": "{nome}: 마리아: '(조용히) 안녕하세요... 지금 예약이 되어 있어요. 죄송해요, 상담은 처음이라서요.'",
   "intro.1a": "알람 끄기",
   "intro.2": "나가기 전에 휴대폰을 잠깐 확인합니다. 접수처에서 메시지를 남겼네요.",
   "intro.2a": "메시지 보기",
   "intro.2from": "클리닉 접수처",
   "intro.2msg": "좋은 아침입니다, {doc}! 오늘은 8시에 마리아, 9시에 루카스가 예약되어 있습니다. 차트는 이미 진료실에 있어요.",
   "intro.3": "노트를 가방에 넣고 심호흡을 합니다.",
   "intro.3a": "가방을 들고 나가기",
   "intro.4": "클리닉까지는 가깝습니다. 마음속으로 되새깁니다. 낙인찍기 전에 듣고, 조언하기 전에 지지하자.",
   "intro.5": "좋은 돌봄은 유대감에서 시작됩니다. 서두른 진단은 환자를 멀어지게 합니다.",
   "intro.6": "간판에 NeuroClin 클리닉이라고 쓰여 있습니다. 가방에서 열쇠를 꺼냅니다.",
   "intro.6a": "문 열기",
   "intro.7": "여기가 당신의 진료실입니다. 상담은 한 번에 50분입니다. 한 주 동안 번 코인으로 꾸미고 확장할 수 있어요.",
   "intro.8": "두 가지가 도움이 됩니다. 알아갈수록 채워지는 환자 차트, 그리고 기준과 접근법이 담긴 진단 매뉴얼입니다.",
   "intro.9": "똑똑... 문 앞에 누가 있습니다. 오늘의 첫 예약, {nome}입니다.",
   "intro.9b": "환자에게 문 열어 주기 ▶",
