   "tip.energia.t": "⚡ 에너지",
   "tip.energia.x": "상담은 매번 힘듭니다. 에너지가 낮으면 답변의 효과가 줄어듭니다. 휴식 시간에 방 안의 물건과 상호작용해 회복하세요.",
   "tip.fala.t": "👂 환자의 말을 들어 보세요",
   "tip.fala.x": "말풍선을 꼼꼼히 읽으세요. 호소 뒤에 무엇이 있는지 단서가 담겨 있습니다.",
   "tip.ficha.t": "📋 차트 업데이트",
   "tip.ficha.x": "빨간 점은 환자에 대해 새로운 것을 알아냈다는 표시입니다. 차트를 눌러 확인하세요.",
   "tip.investigar.t": "🔎 조사하기",
   "tip.investigar.x": "여기를 클릭해서 기분, 수면, 과거력, 위험 요인 등을 직접 물어보세요. 각 답변은 진료 기록과 진단을 위한 진짜 단서가 됩니다.",
   "tip.manual.t": "📖 진단 매뉴얼",
   "tip.manual.x": "기준이나 접근법을 확인해야 하나요? 매뉴얼을 여세요. 사례의 그룹이 확실하지 않다면 {n}코인으로 힌트를 얻을 수 있습니다.",
   "tip.moedas.t": "🪙 코인을 얻었어요!",
   "tip.moedas.x": "상점(위쪽 가방)에서 진료실, 집, 의상을 꾸미는 데 쓰세요.",
   "tip.opcoes.t": "🎯 접근법을 고르세요",
   "tip.opcoes.x": "각 답변은 서로 다른 접근법(지지적, CBT 등)입니다. 환자의 문제에 따라 효과가 다릅니다. A, B, C, D 키도 사용할 수 있습니다.",
   "tip.porta.t": "🚪 다음 상담",
   "tip.porta.x": "문은 일정의 다음 상담을 시작합니다. Ψ는 언제나 이 페이지로 돌아옵니다.",
   "tip.vinculo.t": "💖 유대감",
   "tip.vinculo.x": "이 막대는 환자의 신뢰(0~100%)를 보여 줍니다. 사례에 맞는 접근법은 유대감을 높이고, 맞지 않는 접근법과 판단은 낮춥니다. 마지막에 유대감과 별이 코인이 됩니다.",
   "tips.again": "✓ 팁을 다시 켰습니다",
