   "fu.txwhy.familia": "С детьми и подростками окружение — часть лечения: консультирование семьи и школы часто так же важно, как сама терапия.",
   "fu.txwhy.grupo": "Подходит при проблемном употреблении алкоголя и других веществ: специализированные службы и группы поддержки помогают закрепить перемены.",
   "fu.txwhy.psico": "Подходит, когда состояние хорошо поддаётся психотерапии и нет признаков риска или симптомов, требующих медицинской оценки.",
   "fu.txwhy.psicpsiq": "Подходит, когда симптомы выражены, нарушения значительны или есть риск: психиатр оценивает, нужны ли лекарства. Назначает врач, а не психолог.",
