   "help.intro": "Вы — начинающий специалист ({prof}). Каждый день принимайте пациентов по расписанию и выстраивайте с ними доверие.",
   "help.l1": "<strong>Расписание (Ψ):</strong> показывает приёмы дня. Нажмите на карточку, чтобы увидеть случай, и <em>Начать приём</em> (или дверь), чтобы начать.",
   "help.l2": "<strong>Ответы:</strong> каждый вариант — отдельный <strong>подход</strong> (поддерживающий, КПТ, психодинамический...). Он работает лучше или хуже в зависимости от проблемы пациента. Хорошие выборы повышают <strong>Доверие</strong> и дают <strong>опыт</strong>.",
   "help.l3": "<strong>Карта:</strong> хранит всё, что вы узнали. Заполняется, только если вы задаёте хорошие вопросы.",
   "help.l4": "<strong>Руководство:</strong> содержит группы расстройств, их критерии и подходы. Если вы сомневаетесь, заплатите монеты, чтобы увидеть группу случая.",
   "help.l5": "<strong>Энергия и перерывы:</strong> каждый приём утомляет. Между приёмами есть перерыв: взаимодействуйте с предметами в комнате, чтобы восстановиться.",
   "help.l6": "<strong>Монеты и магазин:</strong> после каждого приёма вы получаете монеты, на которые покупаете декор, расширения кабинета и дома, а также одежду.",
   "help.l7": "<strong>Клавиатура:</strong> во время приёма отвечайте клавишами <kbd>A</kbd> <kbd>B</kbd> <kbd>C</kbd> <kbd>D</kbd> (или <kbd>1</kbd>–<kbd>4</kbd>).",
   "help.l8": "<strong>Город и телефон:</strong> гуляйте по городу (значок карты), разговаривайте с жителями и следите за часами работы магазинов. Каждый пациент возвращается в течение 4 недель; просьбы о терапии приходят в телефон.",
   "help.l9": "<strong>Указатель игры:</strong> на главном экране кнопка 🧭 перечисляет все системы (море, казино, ремонт, друзья, музыка, достижения…) и где их найти.",
   "help.replay": "↺ Повторить обучающие подсказки",
