   "uni.finish": "Посмотреть результат",
   "uni.intro": "Каждое занятие резюмирует группу Руководства. Прочитайте занятие и пройдите тест: 4 вопроса, для зачёта нужно 3 верных. Пройдено: {n} из {total}.",
   "uni.lesson": "Занятие: читайте внимательно. Здесь основные критерии, дифференциальная диагностика и клиническая подсказка для каждого расстройства.",
