   "hair.bob": "波浪波波头",
   "help.intro": "你是一名初入职场的{prof}。每天接待日程表上的来访者，并与他们建立关系。",
   "help.l1": "<strong>日程表（Ψ）：</strong>显示当天的咨询。点击卡片查看个案，再点<em>开始咨询</em>（或门）开始。",
   "help.l2": "<strong>回答：</strong>每个选项都是一种不同的<strong>取向</strong>（支持性、CBT、心理动力学等）。效果好坏取决于来访者的问题。好的选择会提升<strong>关系</strong>并获得<strong>经验值</strong>。",
   "help.l3": "<strong>档案：</strong>保存你已发现的信息。只有提出好问题才会被填满。",
   "help.l4": "<strong>手册：</strong>收录障碍分组、诊断标准和取向。如果迷茫，可以支付金币查看个案所属分组。",
   "help.l5": "<strong>精力与休息：</strong>每场咨询都很累。咨询之间有休息时间：与房间里的物品互动来恢复。",
   "help.l6": "<strong>金币与商店：</strong>每场咨询后你会获得金币，可购买装饰、诊室和家的扩建，以及服装。",
   "help.l7": "<strong>键盘：</strong>咨询中可使用<kbd>A</kbd> <kbd>B</kbd> <kbd>C</kbd> <kbd>D</kbd>键（或<kbd>1</kbd>到<kbd>4</kbd>）作答。",
   "help.l8": "<strong>城市与手机：</strong>通过地图图标逛城市，与居民交谈，并留意商店营业时间。每位患者会回访 4 周；咨询请求会发到手机上。",
   "help.l9": "<strong>游戏索引：</strong>在主界面点击 🧭 按钮，可查看所有系统（大海、赌场、扩建、朋友、音乐、成就等）及其位置。",
