   "idx.ach.t": "成就与守护者",
   "idx.ach.x": "完成挑战以获得成就。在城市中找到四位守护者，完成“守护者传说”。",
   "idx.appx.t": "附录与日程",
   "idx.appx.x": "查看谁已经看过、下一位是谁，以及本周总结。",
   "idx.break.t": "咨询之间的休息",
   "idx.break.x": "十分钟照顾自己：点击房间里的物品来恢复精力。",
   "idx.city.t": "在城市里散步",
   "idx.city.x": "🗺️图标：用WASD或摇杆行走。发现各处地点、聊天，并留意下一场咨询的时间。",
   "idx.cloud.t": "账号与排行榜",
   "idx.cloud.x": "服务器开启时：跨设备同步并比较分数。",
   "idx.consult.t": "与来访者的咨询",
   "idx.consult.x": "每场咨询有4到5个对话步骤。选择最适合这个人和当下时刻的取向。",
   "idx.culture.t": "商场、语言与历史",
   "idx.culture.x": "在商场的语言小店切换游戏语言（含瓜拉尼语），并阅读心理学史。",
   "idx.decor.t": "家与诊室",
   "idx.decor.x": "在商店里装饰并扩建你的诊室、候诊室和厨房。",
   "idx.dress.t": "个性化与试衣间",
   "idx.dress.x": "随时更换脸型、发型和服装。购买前可在试衣间试穿。",
   "idx.dx.t": "诊断假设",
   "idx.dx.x": "每场咨询结束时，选择最一致的假设。答对可额外获得一颗星。",
   "idx.fauna.t": "动物图鉴",
   "idx.fauna.x": "城市、海滩和大海里的所有动物，附栖息地和趣闻。走近它们即可发现。",
   "idx.follow.t": "4 次会话的跟进",
   "idx.follow.x": "每位患者会回访 4 周。诊断要到第 4 次会谈才确定；期间请在手机上回复咨询请求。",
   "idx.help": "你可以做的所有事，以及在哪里做。",
   "idx.leisure.t": "健身房、市场、快餐店和赌场",
   "idx.leisure.x": "照顾好精力和心情，去购物，并享受赌场小游戏（别过度！）。",
   "idx.live.t": "热闹的城市",
   "idx.live.x": "居民按日常作息活动，商店会开门关门，夜里街道变暗。与非患者交谈：说服他们后，下周会预约治疗。",
   "idx.manual.t": "诊断手册",
   "idx.manual.x": "数十种障碍的诊断标准和各种取向。咨询中一有疑问就可以打开。",
   "idx.mind.t": "心智游戏室（小游戏）",
   "idx.mind.x": "在主街上：10 个基于真实测验的游戏（舒尔特、连线、斯特鲁普、数字广度、Simon、Corsi、Go/No-Go、1-back、情绪配对和呼吸）。每个游戏都会说明训练什么；每日奖励在当天第一局获得。",
   "idx.music.t": "音乐与乐器",
   "idx.music.x": "在选项中选择配乐乐器（铃声、钢琴、长笛或竖琴）。每个角色交谈时有主题曲，每位患者在会谈中有专属音色。",
   "idx.npc.t": "友谊",
   "idx.npc.x": "在不同的日子与城里的人交谈。朋友会送你礼物。",
   "idx.opts.t": "选项",
   "idx.opts.x": "语言、声音、3D、提示，以及显示取向的学习模式。",
   "idx.pets.t": "宠物",
   "idx.pets.x": "领养常见或异域的宠物。照顾它们：它们会在咨询中帮忙，还会在城里跟着你。",
