   "instr.piano": "钢琴",
   "intro.1": "星期一，早上6点45分。闹钟响个不停。今天是你在神经评估诊所的第一天。",
   "intro.10": "{nome}: 玛丽亚：“你好……我是在这里预约的吗？我有点紧张。”",
   "intro.10b": "开始咨询 ▶",
   "intro.10v2": "{nome}: 玛丽亚：“下午好……我没走错地方吧？我有点焦虑。”",
   "intro.10v3": "{nome}: 玛丽亚：“（小声）你好……我现在有预约。不好意思，这是我第一次做心理咨询。”",
   "intro.1a": "关掉闹钟",
   "intro.2": "出门前，看一眼手机：前台留了言。",
   "intro.2a": "查看消息",
   "intro.2from": "诊所前台",
   "intro.2msg": "早上好，{doc}！今天：8点玛丽亚，9点卢卡斯。档案已经放在诊室里了。",
   "intro.3": "你把笔记本放进包里，深吸了一口气。",
   "intro.3a": "拿起包出门",
   "intro.4": "去诊所的路不远。你在脑海里默念：先倾听再贴标签，先支持再给建议。",
   "intro.5": "好的照护从关系开始。仓促的诊断会把来访者推开。",
   "intro.6": "招牌上写着NeuroClin诊所。你从包里拿出钥匙。",
   "intro.6a": "打开门",
   "intro.7": "这就是你的诊室。每场咨询持续50分钟。这一周里，你可以用赚到的金币装饰和扩建它。",
   "intro.8": "有两样东西会帮到你：随着你了解情况而逐渐填满的来访者档案，以及包含标准和取向的诊断手册。",
   "intro.9": "咚咚……有人在门口。是{nome}，今天的第一位来访者。",
   "intro.9b": "为来访者开门 ▶",
   "intro.next": "继续 ▶",
   "intro.skip": "跳过开场 ▶▶",
   "lang.gn.note": "瓜拉尼语:翻译未经母语者审校。如果你会瓜拉尼语,非常欢迎你的指正!",
   "leave.confirm": "要离开本次咨询吗？本次咨询的进度将会丢失。",
   "legend.anam": "<strong>初次访谈</strong><br>第一次咨询：倾听主诉、生活史和发育史。",
   "legend.dev": "<strong>反馈会谈</strong><br>反馈结果和报告，并为家庭和学校提供指导。",
   "legend.test": "<strong>测评</strong><br>按标准化流程施测并进行临床观察。",
