   "tut.city2.x": "小地图会显示你（粉色圆点）、重要物品（黄色）以及通往地图的出口（橙色）。",
   "tut.city3.t": "回到地图",
   "tut.city3.x": "点击这里打开地图，前往其他地方。你也可以从每个场所的🚪门出去。",
   "tut.dayend1.t": "时钟与夜晚",
   "tut.dayend1.x": "工作结束了，但一天还没结束。留意时钟：商店有营业时间，晚上会关门，城市也会变暗。加油站全天24小时营业。",
   "tut.dayend2.t": "散步与睡觉",
   "tut.dayend2.x": "用城市按钮出去逛逛：用WASD、方向键或摇杆行走并进入各处。想结束这一天时，回到你的公寓，在床上睡觉：这样新的一天才会开始。",
   "tut.decor1.t": "房间平面图",
   "tut.decor1.x": "在平面图上把家具拖到任意位置。如果碰到其他家具、超出房间或挡住通道，游戏会提示并拒绝。",
   "tut.decor2.t": "旋转与还原",
   "tut.decor2.x": "点选家具后可旋转（或按 R 键）。“原位置”可让它回到初始位置。在装饰店购买更大的房间，空间更多。",
   "tut.dx.t": "诊断假设",
   "tut.dx.x": "在每位患者的最后一次(第4次)咨询中,选择最符合所听内容的假设。答对可得一颗星和经验值。之后是转介。",
   "tut.fauna1.t": "城市小动物",
   "tut.fauna1.x": "这里生活着螃蟹、鸽子、蝴蝶、猫和鱼。靠得太近它们会受惊，慢慢走近才能看清。",
   "tut.feedback.t": "你的话产生的效果",
   "tut.feedback.x": "在这里你可以看到自己用了哪种取向、是否奏效以及原因。同一句话对一位来访者可能很合适，对另一位则不然。",
   "tut.ficha.t": "档案",
   "tut.ficha.x": "这里记录你的发现。它一开始几乎是空的，随着你提出好问题而逐渐填满。",
   "tut.fu.t": "随访",
   "tut.fu.x": "每位患者会来4次,每周2次。诊断和转介只在第4次进行,之后患者可能会请求继续治疗。请求会发到手机上。",
   "tut.manual.t": "诊断手册",
   "tut.manual.x": "你的速查工具：障碍、诊断标准和治疗取向。有疑问时打开它，选择最终假设时也可以用。",
   "tut.map1.t": "城市地图",
   "tut.map1.x": "在这里选择要去的地方。城市分为几个区域：主街（诊所、公寓和商店，你可以步行逛遍）、海滩、广场，以及来访者们所在的街区。",
   "tut.map2.t": "在地图上开车",
   "tut.map2.x": "用方向键、WASD或摇杆把车开到一个地点，然后点击“进入”（或按E）。也可以直接点击该地点。",
   "tut.map3.t": "留意时钟",
   "tut.map3.x": "每次出行大约需要15分钟。咨询迟到会损失关系，所以要时刻留意时间。",
   "tut.mind1.t": "心智游戏室",
   "tut.mind1.x": "走近一个游戏并点击操作按钮。每个小游戏都基于真实测验，结束时会说明训练什么。每日奖励在第一局获得。",
   "tut.npc1.t": "聊天能建立友谊",
   "tut.npc1.x": "在不同的日子与同一个人交谈。聊过三次后，对方就成了朋友，并开始送你礼物。",
   "tut.opts1.t": "选项：按你的方式设置",
   "tut.opts1.x": "在这里可以更改语言、字体和字号、浅色/深色主题、音效和音乐、性能模式以及互动活动。随时都可以修改。",
   "tut.pets1.t": "你的宠物",
   "tut.pets1.x": "每天照顾你的宠物：喂食、玩耍和抚摸都会增进感情。照顾得好，它们会在咨询中帮忙。",
   "tut.phone1.t": "手机消息",
   "tut.phone1.x": "关于即将到来的来访者的消息会连同日期和时间一起送到这里。每场咨询前先读一读：里面有线索。",
   "tut.shop1.t": "只能在商店购买",
   "tut.shop1.x": "在家里只能查看和使用你拥有的物品。要购买，请在地图上前往对应的商店。上锁的物品会显示在哪里可以找到。",
   "tut.souv1.t": "徽章与配饰",
   "tut.souv1.x": "在这里挑选旗帜、公益主题、眼镜和首饰。你购买的东西会显示在旁边的角色身上。",
   "tut.station1.t": "物品与门",
   "tut.station1.x": "靠近可以使用的东西时，会出现带有动作名称的这个按钮。点击它或按E键。",
   "tut.street1.t": "主街",
   "tut.street1.x": "沿街步行，走近建筑的门（或直接点击门），按E进入。招牌会显示营业时间：关门的店会变暗并带有挂锁。出来时你会回到同一扇门。",
   "tut.uni1.t": "大学课程",
   "tut.uni1.x": "选一门课，阅读手册中的诊断标准，然后参加测验。首次通过可获得经验值和金钱；答错会显示正确答案。",
   "tut.vinculo.t": "关系与精力",
   "tut.vinculo.x": "关系显示来访者对你的信任程度，好的选择会让它上升。精力会随每场咨询下降：请在休息时照顾好它。",
   "uni.diploma": "🎓 你通过了所有课程！获得完整文凭。",
