   "hair.bob": "波浪波波頭",
   "help.intro": "你是一名剛入行的{prof}。每天接待行程表上的個案，並與他們建立關係。",
   "help.l1": "<strong>行程表（Ψ）：</strong>顯示當天的諮商。點擊卡片查看個案，再點<em>開始諮商</em>（或門）開始。",
   "help.l2": "<strong>回答：</strong>每個選項都是一種不同的<strong>取向</strong>（支持性、CBT、心理動力等）。效果好壞取決於個案的問題。好的選擇會提升<strong>關係</strong>並獲得<strong>經驗值</strong>。",
   "help.l3": "<strong>檔案：</strong>保存你已發現的資訊。只有提出好問題才會被填滿。",
   "help.l4": "<strong>手冊：</strong>收錄障礙分組、診斷準則和取向。如果迷惘，可以支付金幣查看個案所屬分組。",
   "help.l5": "<strong>精力與休息：</strong>每場諮商都很累。諮商之間有休息時間：與房間裡的物品互動來恢復。",
   "help.l6": "<strong>金幣與商店：</strong>每場諮商後你會獲得金幣，可購買裝飾、診間和家的擴建，以及服裝。",
   "help.l7": "<strong>鍵盤：</strong>諮商中可使用<kbd>A</kbd> <kbd>B</kbd> <kbd>C</kbd> <kbd>D</kbd>鍵（或<kbd>1</kbd>到<kbd>4</kbd>）作答。",
   "help.l8": "<strong>城市與手機：</strong>透過地圖圖示逛城市，與居民交談，並留意商店營業時間。每位患者會回診 4 週；諮商請求會發到手機上。",
   "help.l9": "<strong>遊戲索引：</strong>在主畫面點擊 🧭 按鈕，可查看所有系統（大海、賭場、擴建、朋友、音樂、成就等）及其位置。",
