   "idx.follow.x": "每位患者會回診 4 週。診斷要到第 4 次會談才確定；期間請在手機上回覆諮商請求。",
   "idx.help": "你可以做的所有事，以及在哪裡做。",
   "idx.leisure.t": "健身房、市場、快餐店和賭場",
