   "idx.live.t": "熱鬧的城市",
   "idx.live.x": "居民按日常作息活動，商店會開門關門，夜裡街道變暗。與非患者交談：說服他們後，下週會預約治療。",
   "idx.manual.t": "診斷手冊",
