   "idx.mind.t": "心智遊戲室（小遊戲）",
   "idx.mind.x": "在主街上：10 個基於真實測驗的遊戲（舒爾特、連線、史楚普、數字廣度、Simon、Corsi、Go/No-Go、1-back、情緒配對和呼吸）。每個遊戲都會說明訓練什麼；每日獎勵在當天第一局獲得。",
   "idx.music.t": "音樂與樂器",
   "idx.music.x": "在選項中選擇配樂樂器（鈴聲、鋼琴、長笛或豎琴）。每個角色交談時有主題曲，每位患者在會談中有專屬音色。",
   "idx.npc.t": "友誼",
