   "intro.1": "星期一，早上6點45分。鬧鐘響個不停。今天是你在神經評估診所的第一天。",
   "intro.10": "{nome}: 瑪麗亞：「你好……我是在這裡預約的嗎？我有點緊張。」",
   "intro.10b": "開始諮商 ▶",
   "intro.10v2": "{nome}: 瑪麗亞：「午安……我沒走錯地方吧？我有點焦慮。」",
   "intro.10v3": "{nome}: 瑪麗亞：「（小聲）你好……我現在有預約。不好意思，這是我第一次做心理諮商。」",
   "intro.1a": "關掉鬧鐘",
   "intro.2": "出門前，看一眼手機：櫃檯留了言。",
