   "intro.2from": "診所櫃檯",
   "intro.2msg": "早安，{doc}！今天：8點瑪麗亞，9點盧卡斯。檔案已經放在診間裡了。",
   "intro.3": "你把筆記本放進包包裡，深吸了一口氣。",
   "intro.3a": "拿起包包出門",
   "intro.4": "去診所的路不遠。你在腦海裡默念：先傾聽再貼標籤，先支持再給建議。",
   "intro.5": "好的照護從關係開始。倉促的診斷會把個案推開。",
   "intro.6": "招牌上寫著NeuroClin診所。你從包包裡拿出鑰匙。",
   "intro.6a": "打開門",
   "intro.7": "這就是你的診間。每場諮商持續50分鐘。這一週裡，你可以用賺到的金幣裝飾和擴建它。",
   "intro.8": "有兩樣東西會幫到你：隨著你瞭解情況而逐漸填滿的個案檔案，以及包含準則和取向的診斷手冊。",
   "intro.9": "叩叩……有人在門口。是{nome}，今天的第一位個案。",
